/**
 * Executor API Types
 *
 * These types define the contract between TPMJS and any executor service.
 * Custom executors must implement the ExecuteToolRequest/Response interface.
 */

import { z } from 'zod';

// =============================================================================
// Executor API Specification
// =============================================================================

/**
 * Request payload for POST /execute-tool
 */
export interface ExecuteToolRequest {
  /** NPM package name, e.g., "@tpmjs/hello" */
  packageName: string;
  /** Tool name within the package, e.g., "helloWorld" */
  name: string;
  /** Package version, e.g., "1.0.0" or "latest" */
  version?: string;
  /** Direct esm.sh URL override for the package */
  importUrl?: string;
  /** Tool parameters to pass to execute() */
  params: Record<string, unknown>;
  /** Environment variables to inject during execution */
  env?: Record<string, string>;
}

/**
 * Response from POST /execute-tool
 */
export interface ExecuteToolResponse {
  /** Whether the execution succeeded */
  success: boolean;
  /** Tool output on success */
  output?: unknown;
  /** Error message on failure */
  error?: string;
  /** Execution duration in milliseconds */
  executionTimeMs: number;
}

/**
 * Response from GET /health (optional but recommended)
 */
export interface ExecutorHealthResponse {
  /** Executor status */
  status: 'ok' | 'degraded' | 'error';
  /** Executor version string */
  version?: string;
  /** Optional additional info */
  info?: Record<string, unknown>;
}

// =============================================================================
// Executor Configuration Schemas
// =============================================================================

/**
 * Executor type enum
 */
export const ExecutorTypeSchema = z.enum(['default', 'custom_url']);
export type ExecutorType = z.infer<typeof ExecutorTypeSchema>;

/**
 * Default executor config (uses TPMJS Railway executor)
 */
export const DefaultExecutorConfigSchema = z.object({
  type: z.literal('default'),
});

/**
 * Custom URL executor config
 */
export const CustomUrlExecutorConfigSchema = z.object({
  type: z.literal('custom_url'),
  /** URL of the custom executor (must be HTTPS in production) */
  url: z.string().url(),
  /** Optional API key for Bearer token authentication */
  apiKey: z.string().optional(),
});

/**
 * Union of all executor config types
 */
export const ExecutorConfigSchema = z.discriminatedUnion('type', [
  DefaultExecutorConfigSchema,
  CustomUrlExecutorConfigSchema,
]);

export type ExecutorConfig = z.infer<typeof ExecutorConfigSchema>;
export type DefaultExecutorConfig = z.infer<typeof DefaultExecutorConfigSchema>;
export type CustomUrlExecutorConfig = z.infer<typeof CustomUrlExecutorConfigSchema>;

// =============================================================================
// Zod Schemas for Request/Response Validation
// =============================================================================

export const ExecuteToolRequestSchema = z.object({
  packageName: z.string().min(1),
  name: z.string().min(1),
  version: z.string().optional(),
  importUrl: z.string().url().optional(),
  params: z.record(z.string(), z.unknown()),
  env: z.record(z.string(), z.string()).optional(),
});

export const ExecuteToolResponseSchema = z.object({
  success: z.boolean(),
  output: z.unknown().optional(),
  error: z.string().optional(),
  executionTimeMs: z.number(),
});

export const ExecutorHealthResponseSchema = z.object({
  status: z.enum(['ok', 'degraded', 'error']),
  version: z.string().optional(),
  info: z.record(z.string(), z.unknown()).optional(),
});

// =============================================================================
// Executor Verification
// =============================================================================

export const VerifyExecutorRequestSchema = z.object({
  url: z.string().url(),
  apiKey: z.string().optional(),
});

export interface VerifyExecutorRequest {
  url: string;
  apiKey?: string;
}

export interface VerifyExecutorResponse {
  valid: boolean;
  healthCheck?: ExecutorHealthResponse;
  testExecution?: {
    success: boolean;
    executionTimeMs: number;
  };
  errors?: string[];
}

import { z } from 'zod';

import { ExecutorTypeSchema } from './executor';

// Regex for valid agent UID: lowercase alphanumeric and hyphens
const UID_REGEX = /^[a-z0-9][a-z0-9-]*[a-z0-9]$|^[a-z0-9]$/;

// Executor config for updates (simplified schema that maps to database JSON)
const ExecutorConfigUpdateSchema = z
  .object({
    url: z.string().url(),
    apiKey: z.string().optional(),
  })
  .nullable()
  .optional();

// ============================================================================
// Enums
// ============================================================================

export const AIProviderSchema = z.enum(['OPENAI', 'ANTHROPIC', 'GOOGLE', 'GROQ', 'MISTRAL']);

export const MessageRoleSchema = z.enum(['USER', 'ASSISTANT', 'TOOL', 'SYSTEM']);

export type AIProvider = z.infer<typeof AIProviderSchema>;
export type MessageRole = z.infer<typeof MessageRoleSchema>;

// ============================================================================
// Agent Schemas
// ============================================================================

export const CreateAgentSchema = z.object({
  name: z.string().min(1, 'Name is required').max(100, 'Name must be 100 characters or less'),
  uid: z
    .string()
    .min(1, 'UID is required')
    .max(50, 'UID must be 50 characters or less')
    .regex(UID_REGEX, 'UID must be lowercase alphanumeric with hyphens')
    .optional(),
  description: z.string().max(500, 'Description must be 500 characters or less').optional(),
  provider: AIProviderSchema,
  modelId: z.string().min(1, 'Model ID is required').max(100),
  systemPrompt: z.string().max(10000, 'System prompt must be 10,000 characters or less').optional(),
  temperature: z.number().min(0).max(2).default(0.7),
  maxToolCallsPerTurn: z.number().int().min(1).max(100).default(20),
  maxMessagesInContext: z.number().int().min(1).max(100).default(10),
  isPublic: z.boolean().default(true),
  collectionIds: z.array(z.string()).optional(),
  toolIds: z.array(z.string()).optional(),
});

export const UpdateAgentSchema = z.object({
  name: z.string().min(1).max(100).optional(),
  uid: z.string().min(1).max(50).regex(UID_REGEX).optional(),
  description: z.string().max(500).nullable().optional(),
  provider: AIProviderSchema.optional(),
  modelId: z.string().min(1).max(100).optional(),
  systemPrompt: z.string().max(10000).nullable().optional(),
  temperature: z.number().min(0).max(2).optional(),
  maxToolCallsPerTurn: z.number().int().min(1).max(100).optional(),
  maxMessagesInContext: z.number().int().min(1).max(100).optional(),
  isPublic: z.boolean().optional(),
  // Executor configuration
  executorType: ExecutorTypeSchema.nullable().optional(),
  executorConfig: ExecutorConfigUpdateSchema,
  // Tool environment variables
  envVars: z.record(z.string(), z.string()).nullable().optional(),
});

export const AddCollectionToAgentSchema = z.object({
  collectionId: z.string().min(1, 'Collection ID is required'),
  position: z.number().int().min(0).optional(),
});

export const AddToolToAgentSchema = z.object({
  toolId: z.string().min(1, 'Tool ID is required'),
  position: z.number().int().min(0).optional(),
});

// ============================================================================
// Clone Schemas
// ============================================================================

export const CloneAgentSchema = z.object({
  name: z.string().min(1).max(100).optional(), // If not provided, will append "(copy)"
  uid: z
    .string()
    .min(1)
    .max(50)
    .regex(UID_REGEX, 'UID must be lowercase alphanumeric with hyphens')
    .optional(), // If not provided, will generate from name
});

// ============================================================================
// User API Key Schemas
// ============================================================================

export const SUPPORTED_PROVIDERS = ['OPENAI', 'ANTHROPIC', 'GOOGLE', 'GROQ', 'MISTRAL'] as const;

export const AddApiKeySchema = z.object({
  provider: AIProviderSchema,
  apiKey: z.string().min(10, 'API key is required'),
});

export const ApiKeyInfoSchema = z.object({
  provider: AIProviderSchema,
  keyHint: z.string().nullable(),
  createdAt: z.date(),
  updatedAt: z.date(),
});

// ============================================================================
// Conversation Schemas
// ============================================================================

export const CreateConversationSchema = z.object({
  slug: z
    .string()
    .min(1)
    .max(100)
    .regex(/^[a-z0-9-]+$/, 'Slug must be lowercase alphanumeric with hyphens')
    .optional(),
  title: z.string().max(200).optional(),
});

export const SendMessageSchema = z.object({
  message: z.string().min(1, 'Message is required').max(50000, 'Message too long'),
  env: z.record(z.string(), z.string()).optional(),
  // For non-owners accessing public agents: provide your own LLM API key
  providerApiKey: z.string().optional(),
});

// ============================================================================
// Message Schemas
// ============================================================================

export const ToolCallSchema = z.object({
  id: z.string(),
  name: z.string(),
  arguments: z.string(),
});

export const MessageSchema = z.object({
  id: z.string(),
  role: MessageRoleSchema,
  content: z.string(),
  toolCalls: z.array(ToolCallSchema).nullable(),
  toolCallId: z.string().nullable(),
  toolName: z.string().nullable(),
  toolResult: z.any().nullable(),
  inputTokens: z.number().nullable(),
  outputTokens: z.number().nullable(),
  createdAt: z.date(),
});

// ============================================================================
// Response Types
// ============================================================================

export const AgentSchema = z.object({
  id: z.string(),
  uid: z.string(),
  name: z.string(),
  description: z.string().nullable(),
  provider: AIProviderSchema,
  modelId: z.string(),
  systemPrompt: z.string().nullable(),
  temperature: z.number(),
  maxToolCallsPerTurn: z.number(),
  maxMessagesInContext: z.number(),
  isPublic: z.boolean(),
  toolCount: z.number(),
  collectionCount: z.number(),
  forkCount: z.number().default(0),
  forkedFromId: z.string().nullable().optional(),
  createdAt: z.date(),
  updatedAt: z.date(),
});

export const ConversationSchema = z.object({
  id: z.string(),
  agentId: z.string(),
  slug: z.string(),
  title: z.string().nullable(),
  createdAt: z.date(),
  updatedAt: z.date(),
  messageCount: z.number().optional(),
});

export const ConversationWithMessagesSchema = ConversationSchema.extend({
  messages: z.array(MessageSchema),
});

// ============================================================================
// Type Exports
// ============================================================================

export type CreateAgentInput = z.infer<typeof CreateAgentSchema>;
export type UpdateAgentInput = z.infer<typeof UpdateAgentSchema>;
export type AddCollectionToAgentInput = z.infer<typeof AddCollectionToAgentSchema>;
export type AddToolToAgentInput = z.infer<typeof AddToolToAgentSchema>;
export type CloneAgentInput = z.infer<typeof CloneAgentSchema>;
export type AddApiKeyInput = z.infer<typeof AddApiKeySchema>;
export type ApiKeyInfo = z.infer<typeof ApiKeyInfoSchema>;
export type CreateConversationInput = z.infer<typeof CreateConversationSchema>;
export type SendMessageInput = z.infer<typeof SendMessageSchema>;
export type ToolCall = z.infer<typeof ToolCallSchema>;
export type Message = z.infer<typeof MessageSchema>;
export type Agent = z.infer<typeof AgentSchema>;
export type Conversation = z.infer<typeof ConversationSchema>;
export type ConversationWithMessages = z.infer<typeof ConversationWithMessagesSchema>;

// ============================================================================
// Constants
// ============================================================================

export const AGENT_LIMITS = {
  MAX_AGENTS_PER_USER: 20,
  MAX_COLLECTIONS_PER_AGENT: 10,
  MAX_TOOLS_PER_AGENT: 50,
  MAX_SYSTEM_PROMPT_LENGTH: 10000,
  MAX_NAME_LENGTH: 100,
  MAX_DESCRIPTION_LENGTH: 500,
  MAX_UID_LENGTH: 50,
} as const;

export const CONVERSATION_LIMITS = {
  MAX_CONVERSATIONS_PER_AGENT: 100,
  MAX_MESSAGE_LENGTH: 50000,
  MAX_TITLE_LENGTH: 200,
  MAX_SLUG_LENGTH: 100,
} as const;

// ============================================================================
// Provider Model Mappings
// ============================================================================

export const PROVIDER_MODELS = {
  OPENAI: [
    { id: 'gpt-4.1-mini', name: 'GPT-4.1 Mini', contextWindow: 1000000 },
    { id: 'gpt-4.1', name: 'GPT-4.1', contextWindow: 1000000 },
    { id: '5.1-mini', name: '5.1 Mini', contextWindow: 1000000 },
    { id: 'gpt-4o', name: 'GPT-4o', contextWindow: 128000 },
    { id: 'gpt-4o-mini', name: 'GPT-4o Mini', contextWindow: 128000 },
    { id: 'gpt-4-turbo', name: 'GPT-4 Turbo', contextWindow: 128000 },
    { id: 'gpt-3.5-turbo', name: 'GPT-3.5 Turbo', contextWindow: 16385 },
  ],
  ANTHROPIC: [
    { id: 'claude-3-5-sonnet-20241022', name: 'Claude 3.5 Sonnet', contextWindow: 200000 },
    { id: 'claude-3-5-haiku-20241022', name: 'Claude 3.5 Haiku', contextWindow: 200000 },
    { id: 'claude-3-opus-20240229', name: 'Claude 3 Opus', contextWindow: 200000 },
  ],
  GOOGLE: [
    { id: 'gemini-2.0-flash-exp', name: 'Gemini 2.0 Flash', contextWindow: 1000000 },
    { id: 'gemini-1.5-pro', name: 'Gemini 1.5 Pro', contextWindow: 1000000 },
    { id: 'gemini-1.5-flash', name: 'Gemini 1.5 Flash', contextWindow: 1000000 },
  ],
  GROQ: [
    { id: 'llama-3.3-70b-versatile', name: 'Llama 3.3 70B', contextWindow: 131072 },
    { id: 'llama-3.1-8b-instant', name: 'Llama 3.1 8B', contextWindow: 131072 },
    { id: 'mixtral-8x7b-32768', name: 'Mixtral 8x7B', contextWindow: 32768 },
  ],
  MISTRAL: [
    { id: 'mistral-large-latest', name: 'Mistral Large', contextWindow: 128000 },
    { id: 'mistral-small-latest', name: 'Mistral Small', contextWindow: 128000 },
  ],
} as const;

export type ProviderModel = {
  id: string;
  name: string;
  contextWindow: number;
};

import { z } from 'zod';

import { ExecutorTypeSchema } from './executor';

// Regex for valid collection names: letters, numbers, spaces, hyphens, underscores
const NAME_REGEX = /^[a-zA-Z0-9\s\-_]+$/;

// Executor config for updates (simplified schema that maps to database JSON)
const ExecutorConfigUpdateSchema = z
  .object({
    url: z.string().url(),
    apiKey: z.string().optional(),
  })
  .nullable()
  .optional();

// ============================================================================
// Collection Schemas
// ============================================================================

export const CreateCollectionSchema = z.object({
  name: z
    .string()
    .min(1, 'Name is required')
    .max(100, 'Name must be 100 characters or less')
    .regex(NAME_REGEX, 'Name can only contain letters, numbers, spaces, hyphens, and underscores'),
  description: z.string().max(500, 'Description must be 500 characters or less').optional(),
  isPublic: z.boolean().default(false),
});

export const UpdateCollectionSchema = z.object({
  name: z
    .string()
    .min(1, 'Name is required')
    .max(100, 'Name must be 100 characters or less')
    .regex(NAME_REGEX, 'Name can only contain letters, numbers, spaces, hyphens, and underscores')
    .optional(),
  description: z
    .string()
    .max(500, 'Description must be 500 characters or less')
    .nullable()
    .optional(),
  isPublic: z.boolean().optional(),
  // Executor configuration
  executorType: ExecutorTypeSchema.nullable().optional(),
  executorConfig: ExecutorConfigUpdateSchema,
  // Tool environment variables
  envVars: z.record(z.string(), z.string()).nullable().optional(),
});

// ============================================================================
// Collection Tool Schemas
// ============================================================================

export const AddToolToCollectionSchema = z.object({
  toolId: z.string().min(1, 'Tool ID is required'),
  note: z.string().max(500, 'Note must be 500 characters or less').optional(),
  position: z.number().int().min(0).optional(),
});

export const UpdateCollectionToolSchema = z.object({
  note: z.string().max(500, 'Note must be 500 characters or less').nullable().optional(),
  position: z.number().int().min(0).optional(),
});

export const ReorderToolsSchema = z.object({
  toolIds: z.array(z.string().min(1)),
});

// ============================================================================
// Bulk Add Tools from Package Schema
// ============================================================================

export const BulkAddToolsFromPackageSchema = z.object({
  npmPackageName: z.string().min(1, 'Package name is required').max(214),
});

export type BulkAddToolsFromPackageInput = z.infer<typeof BulkAddToolsFromPackageSchema>;

// ============================================================================
// Bridge Tool Schemas
// ============================================================================

export const AddBridgeToolToCollectionSchema = z.object({
  serverId: z.string().min(1, 'Server ID is required').max(100),
  toolName: z.string().min(1, 'Tool name is required').max(100),
  displayName: z.string().max(100).optional(),
  note: z.string().max(500, 'Note must be 500 characters or less').optional(),
});

export const UpdateCollectionBridgeToolSchema = z.object({
  displayName: z.string().max(100).nullable().optional(),
  note: z.string().max(500, 'Note must be 500 characters or less').nullable().optional(),
});

// ============================================================================
// Custom MCP Server Schemas
// ============================================================================

export const AddCustomMcpServerSchema = z.object({
  name: z.string().min(1, 'Name is required').max(100, 'Name must be 100 characters or less'),
  url: z
    .string()
    .url('Must be a valid URL')
    .refine(
      (url) => url.startsWith('http://') || url.startsWith('https://'),
      'URL must start with http:// or https://'
    ),
  authType: z.enum(['bearer', 'header']).nullable().optional(),
  authHeader: z.string().max(100).optional(),
  authToken: z.string().optional(),
});

export const UpdateCustomMcpServerSchema = z.object({
  name: z.string().min(1).max(100).optional(),
  authType: z.enum(['bearer', 'header']).nullable().optional(),
  authHeader: z.string().max(100).nullable().optional(),
  authToken: z.string().nullable().optional(),
});

export const AddCustomToolToCollectionSchema = z.object({
  serverId: z.string().min(1, 'Server ID is required'),
  toolName: z.string().min(1, 'Tool name is required').max(200),
  displayName: z.string().max(100).optional(),
  note: z.string().max(500, 'Note must be 500 characters or less').optional(),
});

export const UpdateCollectionCustomToolSchema = z.object({
  displayName: z.string().max(100).nullable().optional(),
  note: z.string().max(500, 'Note must be 500 characters or less').nullable().optional(),
});

// ============================================================================
// Clone Schemas
// ============================================================================

export const CloneCollectionSchema = z.object({
  name: z
    .string()
    .min(1, 'Name is required')
    .max(100, 'Name must be 100 characters or less')
    .regex(NAME_REGEX, 'Name can only contain letters, numbers, spaces, hyphens, and underscores')
    .optional(), // If not provided, will use original name or append "(copy)"
});

// ============================================================================
// Use Case Types (AI-generated workflows)
// ============================================================================

export const UseCaseToolStepSchema = z.object({
  toolName: z.string().describe('Name of the tool being invoked'),
  packageName: z.string().describe('NPM package name containing the tool'),
  purpose: z.string().max(100).describe('Why this tool is called at this step'),
  order: z.number().int().min(1).describe('Execution order (1-based)'),
});

export const UseCaseSchema = z.object({
  id: z.string().describe('Unique identifier for this use case'),
  userPrompt: z
    .string()
    .min(20)
    .max(200)
    .describe('Example user prompt that triggers this workflow'),
  description: z.string().min(30).max(150).describe('Brief description of what this accomplishes'),
  toolSequence: z
    .array(UseCaseToolStepSchema)
    .min(1)
    .max(10)
    .describe('Ordered sequence of tool calls'),
});

export const CollectionUseCasesSchema = z.array(UseCaseSchema).max(6);

export type UseCaseToolStep = z.infer<typeof UseCaseToolStepSchema>;
export type UseCase = z.infer<typeof UseCaseSchema>;
export type CollectionUseCases = z.infer<typeof CollectionUseCasesSchema>;

// ============================================================================
// Response Types (for API responses)
// ============================================================================

export const CollectionSchema = z.object({
  id: z.string(),
  name: z.string(),
  slug: z.string().nullable(),
  description: z.string().nullable(),
  isPublic: z.boolean(),
  toolCount: z.number(),
  forkCount: z.number().default(0),
  forkedFromId: z.string().nullable().optional(),
  useCases: CollectionUseCasesSchema.nullable().optional(),
  useCasesGeneratedAt: z.date().nullable().optional(),
  createdAt: z.date(),
  updatedAt: z.date(),
});

export const CollectionToolSchema = z.object({
  id: z.string(),
  toolId: z.string(),
  position: z.number(),
  note: z.string().nullable(),
  addedAt: z.date(),
  tool: z.object({
    id: z.string(),
    name: z.string(),
    description: z.string(),
    package: z.object({
      id: z.string(),
      npmPackageName: z.string(),
      category: z.string(),
    }),
  }),
});

export const CollectionWithToolsSchema = CollectionSchema.extend({
  tools: z.array(CollectionToolSchema),
});

