493→/**
494→ * GET /api/chat/[username]/[uid]/conversation/[conversationId]
495→ * Retrieve conversation history with pagination
496→ *
497→ * Query params:
498→ * - limit: Max messages to return (default: 50, max: 100)
499→ * - before: Fetch messages created before this ISO timestamp (for loading older messages)
500→ * - after: Fetch messages created after this ISO timestamp (for loading newer messages)
501→ *
502→ * Default behavior (no before/after): Returns the most recent messages
503→ * With before: Returns messages older than the timestamp (for scrolling up)
504→ * With after: Returns messages newer than the timestamp (for refreshing)
505→ */
506→export async function GET(request: NextRequest, context: RouteContext): Promise<NextResponse> {
507→  const { username, uid, conversationId } = await context.params;
508→  const { searchParams } = new URL(request.url);
509→
510→  const limit = Math.min(Number.parseInt(searchParams.get('limit') || '50', 10), 100);
511→  const before = searchParams.get('before');
512→  const after = searchParams.get('after');
513→
514→  try {
515→    // Fetch agent by username and uid
516→    const agent = await findAgentByUsernameAndUid(username, uid);
517→
518→    if (!agent) {
519→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
520→    }
521→
522→    // Fetch conversation
523→    const conversation = await prisma.conversation.findUnique({
524→      where: {
525→        agentId_slug: {
526→          agentId: agent.id,
527→          slug: conversationId,
528→        },
529→      },
530→    });
531→
532→    if (!conversation) {
533→      return NextResponse.json(
534→        { success: false, error: 'Conversation not found' },
535→        { status: 404 }
536→      );
537→    }
538→
539→    // Build the where clause based on cursor
540→    const whereClause: {
541→      conversationId: string;
542→      createdAt?: { lt?: Date; gt?: Date };
543→    } = { conversationId: conversation.id };
544→
545→    if (before) {
546→      whereClause.createdAt = { lt: new Date(before) };
547→    } else if (after) {
548→      whereClause.createdAt = { gt: new Date(after) };
549→    }
550→
551→    // Determine fetch order:
552→    // - Default (no cursor) or "before": Fetch desc (newest first), then reverse for chronological order
553→    // - "after": Fetch asc (oldest first) to get messages after the cursor
554→    const shouldFetchDesc = !after;
555→
556→    // Fetch messages
557→    const messages = await prisma.message.findMany({
558→      where: whereClause,
559→      orderBy: { createdAt: shouldFetchDesc ? 'desc' : 'asc' },
560→      take: limit + 1,
561→    });
562→
563→    const hasMore = messages.length > limit;
564→    let paginatedMessages = hasMore ? messages.slice(0, limit) : messages;
565→
566→    // Reverse if we fetched in desc order to maintain chronological order
567→    if (shouldFetchDesc) {
568→      paginatedMessages = paginatedMessages.reverse();
569→    }
570→
571→    const mappedMessages = paginatedMessages.map((m) => ({
572→      id: m.id,
573→      role: m.role,
574→      content: m.content,
575→      toolCalls: m.toolCalls,
576→      toolCallId: m.toolCallId,
577→      toolName: m.toolName,
578→      toolResult: m.toolResult,
579→      inputTokens: m.inputTokens,
580→      outputTokens: m.outputTokens,
581→      createdAt: m.createdAt,
582→    }));
583→
584→    return NextResponse.json({
585→      success: true,
586→      data: {
587→        id: conversation.id,
588→        slug: conversation.slug,
589→        title: conversation.title,
590→        createdAt: conversation.createdAt,
591→        updatedAt: conversation.updatedAt,
592→        messages: mappedMessages,
593→      },
594→      pagination: {
595→        limit,
596→        hasMore,
597→        ...(before && { before }),
598→        ...(after && { after }),
599→      },
600→    });
601→  } catch (error) {
602→    console.error('Failed to fetch conversation:', error);
603→    return NextResponse.json(
604→      { success: false, error: 'Failed to fetch conversation' },
605→      { status: 500 }
606→    );
607→  }
608→}
