  1→/**
  2→ * Agent Conversation Endpoint (ID-based version)
  3→ *
  4→ * POST: Send a message and stream the AI response
  5→ * GET: Retrieve conversation history
  6→ * DELETE: Delete a conversation
  7→ *
  8→ * This endpoint uses agent id directly for dashboard usage.
  9→ *
 10→ * Authentication: Supports both session auth and TPMJS API key auth.
 11→ * Requires 'agent:chat' scope for API key access.
 12→ */
 13→
 14→import { Prisma, prisma } from '@tpmjs/db';
 15→import type { AIProvider } from '@tpmjs/types/agent';
 16→import { SendMessageSchema } from '@tpmjs/types/agent';
 17→import type { LanguageModel, ModelMessage } from 'ai';
 18→import { type NextRequest, NextResponse } from 'next/server';
 19→import { decryptApiKey } from '@/lib/crypto/api-keys';
 20→import { logActivity } from '~/lib/activity';
 21→import { authenticateRequest, hasScope } from '~/lib/api-keys/middleware';
 22→import { trackUsage } from '~/lib/api-keys/usage';
 23→import { checkRateLimit, type RateLimitConfig } from '~/lib/rate-limit';
 24→import { trackExecution } from '~/lib/tracking/executions';
 25→
 26→/**
 27→ * Rate limit for chat messages: 30 requests per minute
 28→ * This is stricter than default because chat involves expensive LLM calls
 29→ */
 30→const CHAT_RATE_LIMIT: RateLimitConfig = {
 31→  limit: 30,
 32→  windowSeconds: 60,
 33→};
 34→
 35→export const runtime = 'nodejs';
 36→export const dynamic = 'force-dynamic';
 37→export const maxDuration = 300; // 5 minutes for long agentic runs
 38→
 39→type RouteContext = {
 40→  params: Promise<{ id: string; conversationId: string }>;
 41→};
 42→
 43→/**
 44→ * Get AI provider SDK based on provider type
 45→ */
 46→async function getProviderModel(
 47→  provider: AIProvider,
 48→  modelId: string,
 49→  apiKey: string
 50→): Promise<LanguageModel> {
 51→  switch (provider) {
 52→    case 'OPENAI': {
 53→      const { createOpenAI } = await import('@ai-sdk/openai');
 54→      return createOpenAI({ apiKey })(modelId);
 55→    }
 56→    case 'ANTHROPIC': {
 57→      const { createAnthropic } = await import('@ai-sdk/anthropic');
 58→      return createAnthropic({ apiKey })(modelId);
 59→    }
 60→    case 'GOOGLE': {
 61→      const { createGoogleGenerativeAI } = await import('@ai-sdk/google');
 62→      return createGoogleGenerativeAI({ apiKey })(modelId);
 63→    }
 64→    case 'GROQ': {
 65→      const { createGroq } = await import('@ai-sdk/groq');
 66→      return createGroq({ apiKey })(modelId);
 67→    }
 68→    case 'MISTRAL': {
 69→      const { createMistral } = await import('@ai-sdk/mistral');
 70→      return createMistral({ apiKey })(modelId);
 71→    }
 72→    default:
 73→      throw new Error(`Unsupported provider: ${provider}`);
 74→  }
 75→}
