 43→/**
 44→ * Get AI provider SDK based on provider type
 45→ */
 46→async function getProviderModel(
 47→  provider: AIProvider,
 48→  modelId: string,
 49→  apiKey: string
 50→): Promise<LanguageModel> {
 51→  switch (provider) {
 52→    case 'OPENAI': {
 53→      const { createOpenAI } = await import('@ai-sdk/openai');
 54→      return createOpenAI({ apiKey })(modelId);
 55→    }
 56→    case 'ANTHROPIC': {
 57→      const { createAnthropic } = await import('@ai-sdk/anthropic');
 58→      return createAnthropic({ apiKey })(modelId);
 59→    }
 60→    case 'GOOGLE': {
 61→      const { createGoogleGenerativeAI } = await import('@ai-sdk/google');
 62→      return createGoogleGenerativeAI({ apiKey })(modelId);
 63→    }
 64→    case 'GROQ': {
 65→      const { createGroq } = await import('@ai-sdk/groq');
 66→      return createGroq({ apiKey })(modelId);
 67→    }
 68→    case 'MISTRAL': {
 69→      const { createMistral } = await import('@ai-sdk/mistral');
 70→      return createMistral({ apiKey })(modelId);
 71→    }
 72→    default:
 73→      throw new Error(`Unsupported provider: ${provider}`);
 74→  }
 75→}
