621→/**
622→ * GET /api/[username]/agents/[agentSlug]/conversation/[conversationId]
623→ * Retrieve conversation history with pagination
624→ */
625→export async function GET(request: NextRequest, context: RouteContext): Promise<NextResponse> {
626→  const { username, agentSlug, conversationId } = await context.params;
627→  const { searchParams } = new URL(request.url);
628→
629→  const format = searchParams.get('format');
630→  const limit = Math.min(Number.parseInt(searchParams.get('limit') || '50', 10), 100);
631→  const before = searchParams.get('before');
632→  const after = searchParams.get('after');
633→
634→  try {
635→    // Fetch agent by username and slug
636→    const agent = await prisma.agent.findFirst({
637→      where: {
638→        uid: agentSlug,
639→        user: { username },
640→      },
641→      select: {
642→        id: true,
643→        uid: true,
644→        name: true,
645→        provider: true,
646→        modelId: true,
647→        executorType: true,
648→        executorConfig: true,
649→      },
650→    });
651→
652→    if (!agent) {
653→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
654→    }
655→
656→    // Fetch conversation
657→    const conversation = await prisma.conversation.findUnique({
658→      where: {
659→        agentId_slug: {
660→          agentId: agent.id,
661→          slug: conversationId,
662→        },
663→      },
664→    });
665→
666→    if (!conversation) {
667→      return NextResponse.json(
668→        { success: false, error: 'Conversation not found' },
669→        { status: 404 }
670→      );
671→    }
672→
673→    // For JSON format, return all messages with full details
674→    if (format === 'json') {
675→      const allMessages = await prisma.message.findMany({
676→        where: { conversationId: conversation.id },
677→        orderBy: { createdAt: 'asc' },
678→      });
679→
680→      const response = {
681→        _meta: {
682→          exportedAt: new Date().toISOString(),
683→          format: 'tpmjs-conversation-log',
684→          version: '1.0',
685→        },
686→        agent: {
687→          id: agent.id,
688→          uid: agent.uid,
689→          name: agent.name,
690→          provider: agent.provider,
691→          modelId: agent.modelId,
692→          executorType: agent.executorType,
693→          executorConfig: agent.executorConfig,
694→        },
695→        conversation: {
696→          id: conversation.id,
697→          slug: conversation.slug,
698→          title: conversation.title,
699→          createdAt: conversation.createdAt,
700→          updatedAt: conversation.updatedAt,
701→          messageCount: allMessages.length,
702→        },
703→        messages: allMessages.map((m) => ({
704→          id: m.id,
705→          role: m.role,
706→          content: m.content,
707→          toolCalls: m.toolCalls,
708→          toolCallId: m.toolCallId,
709→          toolName: m.toolName,
710→          toolResult: m.toolResult,
711→          inputTokens: m.inputTokens,
712→          outputTokens: m.outputTokens,
713→          createdAt: m.createdAt,
714→        })),
715→        stats: {
716→          totalMessages: allMessages.length,
717→          userMessages: allMessages.filter((m) => m.role === 'USER').length,
718→          assistantMessages: allMessages.filter((m) => m.role === 'ASSISTANT').length,
719→          toolResults: allMessages.filter((m) => m.role === 'TOOL').length,
720→          totalInputTokens: allMessages.reduce((sum, m) => sum + (m.inputTokens || 0), 0),
721→          totalOutputTokens: allMessages.reduce((sum, m) => sum + (m.outputTokens || 0), 0),
722→        },
723→      };
724→
725→      // Return pretty-printed JSON with proper content type
726→      return new NextResponse(JSON.stringify(response, null, 2), {
727→        headers: {
728→          'Content-Type': 'application/json',
729→          'Content-Disposition': `inline; filename="${conversation.slug}-logs.json"`,
730→        },
731→      });
732→    }
733→
734→    // Standard paginated response
735→    const whereClause: {
736→      conversationId: string;
737→      createdAt?: { lt?: Date; gt?: Date };
738→    } = { conversationId: conversation.id };
739→
740→    if (before) {
741→      whereClause.createdAt = { lt: new Date(before) };
742→    } else if (after) {
743→      whereClause.createdAt = { gt: new Date(after) };
744→    }
745→
746→    // Determine fetch order:
747→    // - Default (no cursor) or "before": Fetch desc (newest first), then reverse for chronological order
748→    // - "after": Fetch asc (oldest first) to get messages after the cursor
749→    const shouldFetchDesc = !after;
750→
751→    // Fetch messages
752→    const messages = await prisma.message.findMany({
753→      where: whereClause,
754→      orderBy: { createdAt: shouldFetchDesc ? 'desc' : 'asc' },
755→      take: limit + 1,
756→    });
757→
758→    const hasMore = messages.length > limit;
759→    let paginatedMessages = hasMore ? messages.slice(0, limit) : messages;
760→
761→    // Reverse if we fetched in desc order to maintain chronological order
762→    if (shouldFetchDesc) {
763→      paginatedMessages = paginatedMessages.reverse();
764→    }
765→
766→    const mappedMessages = paginatedMessages.map((m) => ({
767→      id: m.id,
768→      role: m.role,
769→      content: m.content,
770→      toolCalls: m.toolCalls,
771→      toolCallId: m.toolCallId,
772→      toolName: m.toolName,
773→      toolResult: m.toolResult,
774→      inputTokens: m.inputTokens,
775→      outputTokens: m.outputTokens,
776→      createdAt: m.createdAt,
777→    }));
778→
779→    return NextResponse.json({
780→      success: true,
781→      data: {
782→        id: conversation.id,
783→        slug: conversation.slug,
784→        title: conversation.title,
785→        createdAt: conversation.createdAt,
786→        updatedAt: conversation.updatedAt,
787→        messages: mappedMessages,
788→      },
789→      pagination: {
790→        limit,
791→        hasMore,
792→        ...(before && { before }),
793→        ...(after && { after }),
794→      },
795→    });
796→  } catch (error) {
797→    console.error('Failed to fetch conversation:', error);
798→    return NextResponse.json(
799→      { success: false, error: 'Failed to fetch conversation' },
800→      { status: 500 }
801→    );
802→  }
803→}
804→
805→/**
806→ * DELETE /api/[username]/agents/[agentSlug]/conversation/[conversationId]
807→ * Delete a conversation
808→ */
809→export async function DELETE(_request: NextRequest, context: RouteContext): Promise<NextResponse> {
810→  const { username, agentSlug, conversationId } = await context.params;
811→
812→  try {
