 337→            } catch (error) {
 338→              console.log('  ❌ Config', Object.keys(config), 'failed:', error.message);
 339→            }
 340→          }
 341→        }
 342→
 343→        // Strategy 3: Try calling with first env var value (single-arg pattern)
 344→        if (!factoryResult && env && typeof env === 'object') {
 345→          try {
 346→            const firstValue = Object.values(env)[0];
