 412→        try {
 413→          rawJsonSchema = toolModule.inputSchema.jsonSchema();
 414→        } catch (error) {
 415→          console.warn(`⚠️  Zod jsonSchema() failed for ${cacheKey}:`, error);
 416→        }
 417→      }
 418→
 419→      // Strategy 2: Try AI SDK v6 jsonSchema() wrapper (has .schema property)
 420→      if (!rawJsonSchema && toolModule.inputSchema.schema) {
 421→        console.log(`📋 Using AI SDK jsonSchema.schema for ${cacheKey}`);
 422→        rawJsonSchema = toolModule.inputSchema.schema;
 423→      }
 424→
 425→      // Strategy 2.5: Try AI SDK jsonSchema() wrapper (has .jsonSchema property)
 426→      // Note: Some versions use .jsonSchema instead of .schema
