 683→            }
 684→          }
 685→        }
 686→
 687→        // Strategy 3: Try calling with first env var value (single-arg pattern)
 688→        if (!factoryResult && env && typeof env === 'object') {
 689→          try {
 690→            const firstValue = Object.values(env)[0];
 691→            if (firstValue) {
 692→              console.log(`  Trying: ${toolName}(firstEnvValue)`);
 693→              factoryResult = rawExport(firstValue);
