 926→/**
 927→ * Main request handler — wrapped with crash protection so no single request
 928→ * can take down the process.
 929→ */
 930→async function handler(req: Request): Promise<Response> {
 931→  // Reject requests during shutdown
 932→  if (isShuttingDown) {
 933→    return new Response('Service shutting down', { status: 503 });
 934→  }
 935→
 936→  const url = new URL(req.url);
 937→
 938→  // Add CORS headers
 939→  const headers = {
 940→    'Access-Control-Allow-Origin': '*',
 941→    'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
 942→    'Access-Control-Allow-Headers': 'Content-Type',
 943→  };
 944→
 945→  if (req.method === 'OPTIONS') {
 946→    return new Response(null, { headers });
 947→  }
 948→
 949→  try {
 950→    let response: Response;
 951→
 952→    if (url.pathname === '/health' && req.method === 'GET') {
 953→      response = health();
 954→    } else if (url.pathname === '/load-and-describe' && req.method === 'POST') {
 955→      response = await loadAndDescribe(req);
 956→    } else if (url.pathname === '/list-exports' && req.method === 'POST') {
 957→      response = await listExports(req);
 958→    } else if (url.pathname === '/execute-tool' && req.method === 'POST') {
 959→      response = await executeTool(req);
 960→    } else if (url.pathname === '/cache/stats' && req.method === 'GET') {
 961→      response = cacheStats();
 962→    } else if (url.pathname === '/cache/clear' && req.method === 'POST') {
 963→      response = clearCache();
 964→    } else {
 965→      response = Response.json({ error: 'Not found' }, { status: 404 });
 966→    }
 967→
 968→    // Add CORS headers to response
 969→    Object.entries(headers).forEach(([key, value]) => {
 970→      response.headers.set(key, value);
 971→    });
 972→
 973→    return response;
 974→  } catch (error) {
 975→    console.error('Request handler error:', error);
 976→    return Response.json(
 977→      {
 978→        success: false,
 979→        error: error.message,
 980→      },
 981→      { status: 500, headers }
 982→    );
 983→  }
 984→}
 985→
 986→// ─── Graceful Shutdown ──────────────────────────────────────────────────────
 987→let isShuttingDown = false;
 988→
 989→function handleShutdown(signal: string) {
 990→  if (isShuttingDown) return;
 991→  isShuttingDown = true;
 992→  console.log(`\n🛑 Received ${signal}, shutting down gracefully...`);
 993→  moduleCache.clear();
 994→  // Give in-flight requests a moment to complete
 995→  setTimeout(() => {
 996→    console.log('👋 Goodbye');
 997→    Deno.exit(0);
 998→  }, 5000);
 999→}
1000→
1001→Deno.addSignalListener('SIGTERM', () => handleShutdown('SIGTERM'));
1002→Deno.addSignalListener('SIGINT', () => handleShutdown('SIGINT'));
1003→
1004→// Start server
1005→const port = Number.parseInt(Deno.env.get('PORT') || '3002', 10);
1006→
1007→console.log(`🚀 Railway Tool Executor (Deno) running on port ${port}`);
1008→console.log('📦 HTTP imports: ENABLED');
1009→console.log(`🔗 Health check: http://localhost:${port}/health`);
1010→console.log('🛠️  Endpoints:');
1011→console.log('   POST /load-and-describe - Load tool and get schema');
1012→console.log('   POST /list-exports - List all exports and identify valid tools');
1013→console.log('   POST /execute-tool - Execute a tool with params');
1014→console.log('   POST /cache/clear - Clear module cache');
1015→console.log('   GET /cache/stats - Get cache statistics');
1016→
1017→Deno.serve({ port }, handler);
