async function handleExecuteTool(req: Request): Promise<Response> {
  const startTime = Date.now();

  try {
    const body = await req.json();
    const { packageName, name, version, importUrl, params, env, sessionId } = body;

    if (!packageName || !name) {
      return Response.json(
