  1→/**
  2→ * TPMJS Agent Sandbox Server (Deno)
  3→ *
  4→ * Stateful execution server with session-scoped filesystem persistence.
  5→ * Based on the Railway executor but adds session management so files
  6→ * created by one tool call persist for subsequent calls within the same conversation.
  7→ */
  8→
  9→// Import zod-to-json-schema for Zod v3 support
 10→import { zodToJsonSchema } from 'https://esm.sh/zod-to-json-schema@3.25.0';
 11→
 12→// ─── Crash Protection ───────────────────────────────────────────────────────
 13→globalThis.addEventListener('unhandledrejection', (event) => {
 14→  event.preventDefault();
 15→  console.error('⚠️  Unhandled promise rejection (caught, process continues):', event.reason);
 16→});
 17→
 18→globalThis.addEventListener('error', (event) => {
 19→  console.error('⚠️  Uncaught error (caught, process continues):', event.error || event.message);
 20→  event.preventDefault();
 21→});
 22→
 23→// ─── Configuration ──────────────────────────────────────────────────────────
 24→const PORT = Number(Deno.env.get('PORT') || '3002');
 25→const EXECUTOR_API_KEY = Deno.env.get('EXECUTOR_API_KEY');
 26→const MAX_CONCURRENT_SESSIONS = Number(Deno.env.get('MAX_CONCURRENT_SESSIONS') || '50');
 27→const DEFAULT_SESSION_TTL_SECONDS = Number(Deno.env.get('DEFAULT_SESSION_TTL_SECONDS') || '3600');
 28→const SESSION_DISK_QUOTA_MB = Number(Deno.env.get('SESSION_DISK_QUOTA_MB') || '100');
 29→const SESSIONS_BASE_DIR = '/tmp/tpmjs-sandbox/sessions';
 30→
 31→// Module cache
 32→const CACHE_TTL_MS = 2 * 60 * 1000;
 33→const MAX_CACHE_SIZE = 200;
 34→
 35→interface CacheEntry {
 36→  // biome-ignore lint/suspicious/noExplicitAny: Tool types are dynamic
 37→  module: any;
 38→  expiresAt: number;
 39→  isFactory: boolean;
 40→}
 41→
 42→const moduleCache = new Map<string, CacheEntry>();
 43→
 44→// ─── Session Management ─────────────────────────────────────────────────────
 45→
 46→interface Session {
 47→  sessionId: string;
 48→  workDir: string;
 49→  createdAt: Date;
 50→  expiresAt: Date;
 51→  toolCallCount: number;
 52→}
 53→
 54→const sessions = new Map<string, Session>();
 55→
 56→function getSessionWorkDir(sessionId: string): string {
 57→  // Sanitize sessionId to be filesystem-safe
 58→  const safe = sessionId.replace(/[^a-zA-Z0-9_:-]/g, '_');
 59→  return `${SESSIONS_BASE_DIR}/${safe}/workspace`;
 60→}
 61→
 62→async function createSession(
 63→  sessionId: string,
 64→  timeoutSeconds?: number
 65→): Promise<Session & { resumed: boolean }> {
 66→  const ttl = timeoutSeconds ?? DEFAULT_SESSION_TTL_SECONDS;
 67→
 68→  // Idempotent: if session exists, extend TTL and return it
 69→  const existing = sessions.get(sessionId);
 70→  if (existing) {
 71→    existing.expiresAt = new Date(Date.now() + ttl * 1000);
 72→    console.log(`🔄 Session resumed: ${sessionId} (TTL extended to ${ttl}s)`);
 73→    return { ...existing, resumed: true };
 74→  }
 75→
 76→  // Check concurrent session limit
 77→  if (sessions.size >= MAX_CONCURRENT_SESSIONS) {
 78→    throw new Error(
 79→      `Maximum concurrent sessions reached (${MAX_CONCURRENT_SESSIONS}). Try again later.`
 80→    );
 81→  }
 82→
 83→  const workDir = getSessionWorkDir(sessionId);
 84→
 85→  // Create workspace directory
 86→  await Deno.mkdir(workDir, { recursive: true });
 87→
 88→  const session: Session = {
 89→    sessionId,
 90→    workDir,
 91→    createdAt: new Date(),
 92→    expiresAt: new Date(Date.now() + ttl * 1000),
 93→    toolCallCount: 0,
 94→  };
 95→
 96→  sessions.set(sessionId, session);
 97→  console.log(`✅ Session created: ${sessionId} (TTL: ${ttl}s, workDir: ${workDir})`);
 98→
 99→  return { ...session, resumed: false };
100→}
101→
102→async function destroySession(sessionId: string): Promise<boolean> {
103→  const session = sessions.get(sessionId);
104→  if (!session) {
105→    return false;
106→  }
107→
108→  sessions.delete(sessionId);
109→
110→  // Clean up workspace directory
111→  try {
112→    await Deno.remove(session.workDir, { recursive: true });
113→    // Also remove parent directory (the sessionId dir)
114→    const parentDir = session.workDir.replace(/\/workspace$/, '');
115→    await Deno.remove(parentDir, { recursive: true }).catch(() => {});
116→  } catch {
117→    // Directory may already be cleaned up
118→  }
119→
120→  console.log(`🗑️  Session destroyed: ${sessionId}`);
121→  return true;
122→}
