171→// biome-ignore lint/suspicious/noExplicitAny: Tool types are dynamic
172→function setCachedModule(cacheKey: string, module: any, isFactory: boolean): void {
173→  if (moduleCache.size >= MAX_CACHE_SIZE) {
174→    const entriesToEvict = Math.max(1, Math.floor(MAX_CACHE_SIZE * 0.2));
175→    const keys = Array.from(moduleCache.keys());
176→    for (let i = 0; i < entriesToEvict && i < keys.length; i++) {
177→      moduleCache.delete(keys[i]);
178→    }
179→  }
180→  moduleCache.set(cacheKey, {
181→    module,
182→    expiresAt: Date.now() + CACHE_TTL_MS,
183→    isFactory,
184→  });
185→}
186→
187→function cleanupExpiredCache(): void {
188→  const now = Date.now();
189→  for (const [key, entry] of moduleCache.entries()) {
190→    if (now > entry.expiresAt) {
191→      moduleCache.delete(key);
192→    }
193→  }
194→}
