220→// biome-ignore lint/suspicious/noExplicitAny: Dynamic tool loading
221→async function loadTool(
222→  packageName: string,
223→  name: string,
224→  version: string,
225→  importUrl?: string
226→): Promise<any> {
227→  const cacheKey = `${packageName}::${name}`;
228→
229→  const cached = getCachedModule(cacheKey);
230→  if (cached) {
231→    return cached.module;
232→  }
233→
234→  const url = importUrl || `https://esm.sh/${packageName}@${version}`;
235→  console.log(`📦 Importing: ${url}`);
236→
237→  const module = await import(url);
238→  let rawExport = module[name];
239→
240→  if (!rawExport) {
241→    throw new Error(
242→      `Export "${name}" not found in module. Available: ${Object.keys(module).join(', ')}`
243→    );
244→  }
245→
246→  // Check if it's a factory function
247→  if (typeof rawExport === 'function' && !rawExport.description && !rawExport.execute) {
248→    console.log(`🏭 Detected factory function for ${cacheKey}, attempting to call...`);
249→
250→    let factoryResult = null;
251→
252→    // Strategy 1: no arguments
253→    try {
254→      factoryResult = rawExport();
255→      if (factoryResult?.description && factoryResult?.execute) {
256→        rawExport = factoryResult;
257→      } else {
258→        factoryResult = null;
259→      }
260→    } catch {
261→      factoryResult = null;
262→    }
263→
264→    // Strategy 2: empty config object
265→    if (!factoryResult) {
266→      try {
267→        factoryResult = rawExport({});
268→        if (factoryResult?.description && factoryResult?.execute) {
269→          rawExport = factoryResult;
270→        }
271→      } catch {
272→        // Not a factory
273→      }
274→    }
275→  }
276→
277→  const isFactory = rawExport !== module[name];
278→  setCachedModule(cacheKey, rawExport, isFactory);
279→
280→  return rawExport;
281→}
