 535→async function executeTool(req: Request): Promise<Response> {
 536→  const startTime = Date.now();
 537→  // Declare these before try block so they're available in catch for error reporting
 538→  let packageName = 'unknown';
 539→  let toolName = 'unknown';
 540→  try {
 541→    const body = await req.json();
 542→    const { packageName: pkg, name, version, importUrl, params, env } = body;
 543→    packageName = pkg || 'unknown';
 544→    toolName = name || 'unknown';
 545→
 546→    console.log('📥 Execute request:', {
 547→      packageName,
 548→      name: toolName,
 549→      version,
 550→      envKeys: env ? Object.keys(env) : [],
 551→      envValues: env || {},
 552→    });
 553→
 554→    if (!packageName || !toolName || !version) {
 555→      return Response.json(
 556→        {
 557→          success: false,
 558→          error: 'Missing required fields: packageName, name, version',
 559→        },
 560→        { status: 400 }
 561→      );
 562→    }
 563→
 564→    const cacheKey = `${packageName}::${toolName}`;
 565→
 566→    // Inject environment variables FIRST - before cache check and factory calls
 567→    // This ensures process.env is set when factory functions read from it
 568→    if (env && typeof env === 'object') {
 569→      const envKeys = Object.keys(env);
 570→      if (envKeys.length > 0) {
 571→        console.log(`🔐 Injecting ${envKeys.length} environment variables:`, envKeys);
 572→        for (const [key, value] of Object.entries(env)) {
 573→          const stringValue = String(value);
 574→
 575→          // Set in Deno environment (for esm.sh imports)
 576→          Deno.env.set(key, stringValue);
 577→
 578→          // ALSO set in Node.js process.env (for npm: imports)
 579→          // @ts-expect-error - process is available in Node.js compatibility mode
 580→          if (typeof globalThis.process !== 'undefined' && globalThis.process.env) {
 581→            // @ts-expect-error - process.env exists in Node compat mode
 582→            globalThis.process.env[key] = stringValue;
 583→          }
 584→
 585→          console.log(`  ✅ Set ${key} = ${stringValue.substring(0, 10)}...`);
 586→        }
 587→      } else {
 588→        console.log('⚠️  No env vars provided in request');
 589→      }
 590→    } else {
 591→      console.log('⚠️  No env object in request body');
 592→    }
 593→
 594→    // biome-ignore lint/suspicious/noImplicitAnyLet: Tool type is determined dynamically after import
 595→    let toolModule;
 596→    let needsImport = true;
 597→
 598→    // Check cache first (with TTL) - but skip cache for factory functions
 599→    // since they may read env vars at creation time
 600→    const cachedEntry = getCachedModule(cacheKey);
 601→    if (cachedEntry && !cachedEntry.isFactory) {
 602→      console.log(`✅ Cache hit (non-factory): ${cacheKey}`);
 603→      toolModule = cachedEntry.module;
 604→      needsImport = false;
 605→    } else if (cachedEntry?.isFactory) {
 606→      console.log(`🏭 Cache hit but factory - will re-import: ${cacheKey}`);
 607→    }
 608→
 609→    if (needsImport) {
 610→      const url = importUrl || `https://esm.sh/${packageName}@${version}`;
 611→      console.log(`📦 Importing for execution: ${url}`);
 612→
 613→      const module = await import(url);
