 616→      if (!rawExport) {
 617→        return Response.json(
 618→          {
 619→            success: false,
 620→            error: 'Tool not found',
 621→            executionTimeMs: Date.now() - startTime,
 622→          },
 623→          { status: 404 }
 624→        );
 625→      }
 626→
 627→      // Track if this is a factory function - we won't cache factory-created tools
 628→      // because they may read env vars at creation time
 629→      let isFactoryFunction = false;
 630→
 631→      // Check if it's a factory function (not a direct tool)
 632→      if (typeof rawExport === 'function' && !rawExport.description && !rawExport.execute) {
 633→        console.log(`🏭 Detected factory function for ${cacheKey}, attempting to call...`);
 634→        isFactoryFunction = true;
 635→
 636→        let factoryResult = null;
 637→
 638→        // Strategy 1: Try calling with no arguments
 639→        try {
 640→          console.log(`  Trying: ${toolName}()`);
 641→          factoryResult = rawExport();
 642→          if (factoryResult?.execute) {
 643→            console.log('  ✅ Success with no-args factory');
