 645→          }
 646→        } catch (error) {
 647→          console.log('  ❌ No-args failed:', error.message);
 648→        }
 649→
 650→        // Strategy 2: Try calling with env vars as config object
 651→        if (!factoryResult && env && typeof env === 'object') {
 652→          // Build multiple config variations to try
 653→          const configVariations = [];
 654→
 655→          // Variation 1: Raw env vars (e.g., { VALYU_API_KEY: 'xxx' })
 656→          configVariations.push({ ...env });
 657→
 658→          // Variation 2: Normalized to camelCase apiKey (e.g., { apiKey: 'xxx' })
 659→          const apiKeyValue = Object.entries(env).find(([key]) =>
 660→            key.toUpperCase().includes('API_KEY')
 661→          )?.[1];
 662→          if (apiKeyValue) {
 663→            configVariations.push({ apiKey: apiKeyValue });
 664→          }
 665→
 666→          // Variation 3: Normalized to key (e.g., { key: 'xxx' })
 667→          if (apiKeyValue) {
 668→            configVariations.push({ key: apiKeyValue });
 669→          }
 670→
 671→          // Try each config variation
 672→          for (const config of configVariations) {
 673→            try {
 674→              console.log(`  Trying: ${toolName}(`, Object.keys(config), ')');
 675→              factoryResult = rawExport(config);
 676→              if (factoryResult?.execute) {
 677→                console.log('  ✅ Success with config:', Object.keys(config));
 678→                rawExport = factoryResult;
 679→                break;
 680→              }
 681→            } catch (error) {
 682→              console.log('  ❌ Config', Object.keys(config), 'failed:', error.message);
 683→            }
 684→          }
 685→        }
 686→
 687→        // Strategy 3: Try calling with first env var value (single-arg pattern)
 688→        if (!factoryResult && env && typeof env === 'object') {
 689→          try {
 690→            const firstValue = Object.values(env)[0];
 691→            if (firstValue) {
 692→              console.log(`  Trying: ${toolName}(firstEnvValue)`);
 693→              factoryResult = rawExport(firstValue);
 694→              if (factoryResult?.execute) {
 695→                console.log('  ✅ Success with single-arg factory');
 696→                rawExport = factoryResult;
 697→              }
 698→            }
 699→          } catch (error) {
 700→            console.log('  ❌ Single-arg failed:', error.message);
