  1→/**
  2→ * Discord Post Tool
  3→ * Posts messages and embeds to a Discord channel
  4→ */
  5→
  6→import { jsonSchema, tool } from 'ai';
  7→
  8→// Tool input type
  9→type DiscordPostInput = {
 10→  channelId: string;
 11→  content?: string;
 12→  embed?: {
 13→    title?: string;
 14→    description?: string;
 15→    color?: number;
 16→    fields?: Array<{
 17→      name: string;
 18→      value: string;
 19→      inline?: boolean;
 20→    }>;
 21→    footer?: string;
 22→    timestamp?: string;
 23→  };
 24→};
 25→
 26→const DISCORD_API_BASE = 'https://discord.com/api/v10';
 27→
 28→/**
 29→ * Discord Post Tool
 30→ * Posts a message or rich embed to a Discord channel
 31→ */
 32→export const discordPostTool = tool({
 33→  description:
 34→    'Post a message or rich embed to a Discord channel. Supports plain text messages and formatted embeds with titles, descriptions, colors, and fields.',
 35→  inputSchema: jsonSchema<DiscordPostInput>({
 36→    type: 'object',
 37→    properties: {
 38→      channelId: {
 39→        type: 'string',
 40→        description: 'Discord channel ID to post to',
 41→      },
 42→      content: {
 43→        type: 'string',
 44→        description: 'Plain text message content (max 2000 characters)',
 45→      },
 46→      embed: {
 47→        type: 'object',
 48→        description: 'Rich embed object for formatted messages',
 49→        properties: {
 50→          title: {
 51→            type: 'string',
 52→            description: 'Embed title (max 256 characters)',
 53→          },
 54→          description: {
 55→            type: 'string',
 56→            description: 'Embed description (max 4096 characters)',
 57→          },
 58→          color: {
 59→            type: 'number',
 60→            description: 'Embed color as decimal (e.g., 5793266 for Discord blurple)',
 61→          },
 62→          fields: {
 63→            type: 'array',
 64→            description: 'Array of field objects',
 65→            items: {
 66→              type: 'object',
 67→              properties: {
 68→                name: {
 69→                  type: 'string',
 70→                  description: 'Field name (max 256 chars)',
 71→                },
 72→                value: {
 73→                  type: 'string',
 74→                  description: 'Field value (max 1024 chars)',
 75→                },
 76→                inline: { type: 'boolean', description: 'Display inline' },
 77→              },
 78→              required: ['name', 'value'],
 79→            },
 80→          },
 81→          footer: {
 82→            type: 'string',
 83→            description: 'Footer text (max 2048 characters)',
 84→          },
 85→          timestamp: {
 86→            type: 'string',
 87→            description: 'ISO8601 timestamp to display',
 88→          },
 89→        },
 90→      },
 91→    },
 92→    required: ['channelId'],
 93→    additionalProperties: false,
 94→  }),
 95→  execute: discordPostExecute,
 96→});
 97→
 98→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Discord embed building with validation
 99→async function discordPostExecute(input: DiscordPostInput) {
100→  // Get token from environment - the executor injects this
101→  const token = process.env.DISCORD_BOT_TOKEN;
102→
103→  if (!token) {
104→    return {
105→      success: false,
106→      error: 'DISCORD_BOT_TOKEN environment variable is required',
107→    };
108→  }
109→
110→  // Validate that we have something to post
111→  if (!input.content && !input.embed) {
112→    return {
113→      success: false,
114→      error: 'Either content or embed must be provided',
115→    };
116→  }
117→
118→  // Build the message payload
119→  const payload: {
120→    content?: string;
121→    embeds?: Array<{
122→      title?: string;
123→      description?: string;
124→      color?: number;
125→      fields?: Array<{ name: string; value: string; inline?: boolean }>;
126→      footer?: { text: string };
127→      timestamp?: string;
128→    }>;
129→  } = {};
130→
131→  if (input.content) {
132→    // Truncate to Discord's limit
133→    payload.content = input.content.slice(0, 2000);
134→  }
135→
136→  if (input.embed) {
137→    const embed: {
138→      title?: string;
139→      description?: string;
140→      color?: number;
141→      fields?: Array<{ name: string; value: string; inline?: boolean }>;
142→      footer?: { text: string };
143→      timestamp?: string;
144→    } = {};
145→
146→    if (input.embed.title) {
147→      embed.title = input.embed.title.slice(0, 256);
148→    }
149→
150→    if (input.embed.description) {
151→      embed.description = input.embed.description.slice(0, 4096);
152→    }
153→
154→    if (input.embed.color !== undefined) {
155→      embed.color = input.embed.color;
156→    }
157→
158→    if (input.embed.fields && input.embed.fields.length > 0) {
159→      embed.fields = input.embed.fields.slice(0, 25).map((field) => ({
160→        name: field.name.slice(0, 256),
161→        value: field.value.slice(0, 1024),
162→        inline: field.inline,
163→      }));
164→    }
165→
166→    if (input.embed.footer) {
167→      embed.footer = { text: input.embed.footer.slice(0, 2048) };
168→    }
169→
170→    if (input.embed.timestamp) {
171→      embed.timestamp = input.embed.timestamp;
172→    }
173→
174→    payload.embeds = [embed];
175→  }
176→
177→  try {
178→    const response = await fetch(`${DISCORD_API_BASE}/channels/${input.channelId}/messages`, {
179→      method: 'POST',
180→      headers: {
181→        Authorization: `Bot ${token}`,
182→        'Content-Type': 'application/json',
183→      },
184→      body: JSON.stringify(payload),
185→    });
186→
187→    if (!response.ok) {
188→      const errorText = await response.text();
189→      return {
190→        success: false,
191→        error: `Discord API error (${response.status}): ${errorText}`,
192→      };
193→    }
194→
195→    const message = (await response.json()) as {
196→      id: string;
197→      channel_id: string;
198→      timestamp: string;
199→    };
200→
201→    return {
202→      success: true,
203→      messageId: message.id,
204→      channelId: message.channel_id,
205→      timestamp: message.timestamp,
206→    };
207→  } catch (error) {
208→    return {
209→      success: false,
210→      error: error instanceof Error ? error.message : 'Unknown error occurred',
211→    };
212→  }
213→}
