 19→    if (!table || table.trim().length === 0) {
 20→      return {
 21→        success: false,
 22→        error: 'Missing required parameter: table',
 23→        formattedTable: '',
 24→        rowCount: 0,
 25→        columnCount: 0,
 26→      };
 27→    }
 28→
 29→    // Split into lines and remove empty lines
 30→    const lines = table
 31→      .split('\n')
 32→      .map((line) => line.trim())
 33→      .filter((line) => line.length > 0 && line.startsWith('|'));
 34→
 35→    if (lines.length < 2) {
 36→      return {
 37→        success: false,
 38→        error: 'Invalid table format: need at least header and separator rows',
 39→        formattedTable: table,
 40→        rowCount: lines.length,
 41→        columnCount: 0,
 42→      };
 43→    }
 44→
 45→    // Parse table rows
 46→    const rows = lines.map((line) =>
 47→      line
 48→        .split('|')
 49→        .slice(1, -1)
 50→        .map((cell) => cell.trim())
 51→    );
 52→
 53→    // Calculate column widths
 54→    const columnCount = rows[0]?.length || 0;
 55→    const columnWidths = new Array(columnCount).fill(0);
 56→
 57→    for (const row of rows) {
 58→      for (let i = 0; i < row.length; i++) {
 59→        const cell = row[i];
 60→        const currentWidth = columnWidths[i];
 61→        // Skip separator row when calculating widths
 62→        if (cell && !cell.match(/^:?-+:?$/)) {
