 69→    const alignmentMarkers = columnWidths.map((width) => {
 70→      const dashes = '-'.repeat(Math.max(3, width));
 71→      if (alignment === 'center') return `:${dashes}:`;
 72→      if (alignment === 'right') return `${dashes}:`;
