 76→    // Build formatted table
 77→    const formattedRows: string[] = [];
 78→
 79→    for (let i = 0; i < rows.length; i++) {
 80→      const row = rows[i];
 81→      if (!row) continue;
 82→
 83→      // Check if this is the separator row
