344→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Tool execution with session support
345→async function handleExecuteTool(req: Request): Promise<Response> {
346→  const startTime = Date.now();
347→
348→  try {
349→    const body = await req.json();
350→    const { packageName, name, version, importUrl, params, env, sessionId } = body;
351→
352→    if (!packageName || !name) {
353→      return Response.json(
354→        { success: false, error: 'Missing required fields: packageName, name' },
355→        { status: 400, headers: corsHeaders() }
356→      );
357→    }
358→
359→    // Load the tool
360→    const tool = await loadTool(packageName, name, version || 'latest', importUrl);
361→
362→    if (!tool || typeof tool.execute !== 'function') {
363→      return Response.json(
364→        { success: false, error: `"${name}" is not a valid tool (missing execute function)` },
365→        { status: 400, headers: corsHeaders() }
366→      );
367→    }
368→
369→    // Resolve session workspace for cwd if sessionId provided
370→    let cwd: string | undefined;
371→    if (sessionId) {
372→      const session = getSession(sessionId);
373→      if (session) {
374→        cwd = session.workDir;
375→        session.toolCallCount++;
376→        // Extend session TTL on each tool call
377→        session.expiresAt = new Date(Date.now() + DEFAULT_SESSION_TTL_SECONDS * 1000);
378→      }
379→    }
380→
381→    // Set environment variables if provided
382→    if (env && typeof env === 'object') {
383→      for (const [key, value] of Object.entries(env)) {
384→        if (typeof value === 'string') {
385→          Deno.env.set(key, value);
386→        }
387→      }
388→    }
389→
390→    // Execute the tool, injecting cwd into params if session is active
391→    const executeParams = cwd ? { ...params, _sandboxWorkDir: cwd } : params;
392→    const output = await tool.execute(executeParams);
393→
394→    // Clean up injected env vars
395→    if (env && typeof env === 'object') {
396→      for (const key of Object.keys(env)) {
397→        try {
398→          Deno.env.delete(key);
399→        } catch {
400→          // Some vars may be read-only
401→        }
402→      }
403→    }
404→
405→    const executionTimeMs = Date.now() - startTime;
406→
407→    return Response.json(
408→      { success: true, output, executionTimeMs },
409→      { status: 200, headers: corsHeaders() }
410→    );
411→  } catch (error) {
412→    const executionTimeMs = Date.now() - startTime;
413→    const message = error instanceof Error ? error.message : String(error);
414→    console.error('❌ Execute tool error:', message);
415→
416→    return Response.json(
417→      { success: false, error: message, executionTimeMs },
418→      { status: 200, headers: corsHeaders() }
419→    );
420→  }
421→}
422→
423→function handleHealth(): Response {
424→  return Response.json(
425→    {
426→      status: 'ok',
427→      version: '1.0.0',
428→      info: {
429→        runtime: 'deno',
430→        denoVersion: Deno.version.deno,
431→        activeSessions: sessions.size,
432→        maxSessions: MAX_CONCURRENT_SESSIONS,
433→        cachedModules: moduleCache.size,
434→        capabilities: {
435→          sessions: true,
436→          executeToolWithSession: true,
437→        },
438→      },
439→    },
440→    { status: 200, headers: corsHeaders() }
441→  );
442→}
443→
444→// ─── Request Router ─────────────────────────────────────────────────────────
445→
446→async function handler(req: Request): Promise<Response> {
447→  const url = new URL(req.url);
448→  const { pathname } = url;
449→  const method = req.method;
450→
451→  // CORS preflight
452→  if (method === 'OPTIONS') {
453→    return new Response(null, { status: 204, headers: corsHeaders() });
454→  }
455→
456→  // Health check (no auth required)
457→  if (pathname === '/health' && method === 'GET') {
458→    return handleHealth();
459→  }
460→
461→  // Auth check for all other routes
462→  if (!checkAuth(req)) {
463→    return Response.json({ error: 'Unauthorized' }, { status: 401, headers: corsHeaders() });
464→  }
465→
466→  // Session endpoints
467→  if (pathname === '/sessions' && method === 'POST') {
468→    return handleCreateSession(req);
469→  }
470→
471→  const sessionMatch = pathname.match(/^\/sessions\/(.+)$/);
472→  if (sessionMatch) {
473→    const sessionId = decodeURIComponent(sessionMatch[1]);
474→    if (method === 'GET') {
475→      return handleGetSession(sessionId);
476→    }
477→    if (method === 'DELETE') {
478→      return handleDestroySession(sessionId);
479→    }
480→  }
481→
482→  // Tool execution
483→  if (pathname === '/execute-tool' && method === 'POST') {
484→    return handleExecuteTool(req);
485→  }
486→
487→  return Response.json({ error: 'Not Found' }, { status: 404, headers: corsHeaders() });
488→}
489→
490→// ─── Server Startup ─────────────────────────────────────────────────────────
491→
492→// Ensure sessions directory exists
493→try {
494→  await Deno.mkdir(SESSIONS_BASE_DIR, { recursive: true });
495→} catch {
496→  // May already exist
497→}
498→
499→console.log(`🚀 TPMJS Agent Sandbox Server starting on port ${PORT}`);
500→console.log(`📁 Sessions base dir: ${SESSIONS_BASE_DIR}`);
501→console.log(`🔒 Auth: ${EXECUTOR_API_KEY ? 'enabled' : 'disabled'}`);
502→console.log(`📊 Max sessions: ${MAX_CONCURRENT_SESSIONS}, TTL: ${DEFAULT_SESSION_TTL_SECONDS}s`);
503→
504→Deno.serve({ port: PORT }, handler);
505→
506→// ─── Graceful Shutdown ──────────────────────────────────────────────────────
507→
508→async function shutdown(signal: string) {
509→  console.log(`\n${signal} received. Cleaning up ${sessions.size} sessions...`);
510→
511→  // Destroy all sessions
512→  for (const sessionId of sessions.keys()) {
513→    await destroySession(sessionId).catch(() => {});
514→  }
515→
516→  console.log('✅ Cleanup complete. Exiting.');
517→  Deno.exit(0);
518→}
519→
520→Deno.addSignalListener('SIGTERM', () => shutdown('SIGTERM'));
521→Deno.addSignalListener('SIGINT', () => shutdown('SIGINT'));
