  1→/**
  2→ * Fetch Text Tool for TPMJS
  3→ * Fetches a URL and returns plain text content with metadata.
  4→ * Strips HTML tags and returns clean text.
  5→ *
  6→ * @requires Node.js 18+ (uses native fetch API)
  7→ */
  8→
  9→import { jsonSchema, tool } from 'ai';
 10→
 11→// Verify fetch is available (Node.js 18+)
 12→if (typeof globalThis.fetch !== 'function') {
 13→  throw new Error('Fetch Text tool requires Node.js 18+ with native fetch support');
 14→}
 15→
 16→/**
 17→ * Output interface for the fetch text result
 18→ */
 19→export interface FetchResult {
 20→  text: string;
 21→  url: string;
 22→  contentLength: number;
 23→  contentType: string;
 24→  metadata: {
 25→    fetchedAt: string;
 26→    statusCode: number;
 27→    redirected: boolean;
 28→    finalUrl: string;
 29→  };
 30→}
 31→
 32→type FetchTextInput = {
 33→  url: string;
 34→  maxBytes?: number;
 35→  timeoutMs?: number;
 36→};
 37→
 38→/**
 39→ * Validates that a string is a valid URL
 40→ */
 41→function isValidUrl(urlString: string): boolean {
 42→  try {
 43→    const url = new URL(urlString);
 44→    return url.protocol === 'http:' || url.protocol === 'https:';
 45→  } catch {
 46→    return false;
 47→  }
 48→}
 49→
 50→/**
 51→ * Strips HTML tags from a string and returns plain text
 52→ */
 53→function stripHtmlTags(html: string): string {
 54→  // Remove script and style elements completely
 55→  let text = html.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
 56→  text = text.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');
 57→
 58→  // Remove all HTML tags
 59→  text = text.replace(/<[^>]+>/g, ' ');
 60→
 61→  // Decode common HTML entities
 62→  const entities: Record<string, string> = {
 63→    '&amp;': '&',
 64→    '&lt;': '<',
 65→    '&gt;': '>',
 66→    '&quot;': '"',
 67→    '&#39;': "'",
 68→    '&apos;': "'",
 69→    '&nbsp;': ' ',
 70→  };
 71→
 72→  text = text.replace(/&[a-z]+;|&#\d+;/gi, (match) => {
 73→    return entities[match.toLowerCase()] || match;
 74→  });
 75→
 76→  // Normalize whitespace
 77→  text = text.replace(/\s+/g, ' ').trim();
 78→
 79→  return text;
 80→}
 81→
 82→/**
 83→ * Fetch Text Tool
 84→ * Fetches a URL and returns plain text content with metadata
 85→ */
 86→export const fetchTextTool = tool({
 87→  description:
 88→    'Fetch a URL and return plain text content. Automatically strips HTML tags and returns clean text with metadata including content type, length, and status code. Useful for extracting text from web pages.',
 89→  inputSchema: jsonSchema<FetchTextInput>({
 90→    type: 'object',
 91→    properties: {
 92→      url: {
 93→        type: 'string',
 94→        description: 'The URL to fetch (must be http or https)',
 95→      },
 96→      maxBytes: {
 97→        type: 'number',
 98→        description: 'Maximum bytes to read from response (default: unlimited)',
 99→      },
100→      timeoutMs: {
101→        type: 'number',
102→        description: 'Request timeout in milliseconds (default: 30000)',
103→      },
104→    },
105→    required: ['url'],
106→    additionalProperties: false,
107→  }),
108→  async execute({ url, maxBytes, timeoutMs }): Promise<FetchResult> {
109→    // Validate URL
110→    if (!url || typeof url !== 'string') {
111→      throw new Error('URL is required and must be a string');
112→    }
113→
114→    if (!isValidUrl(url)) {
115→      throw new Error(`Invalid URL: ${url}. Must be a valid http or https URL.`);
116→    }
117→
118→    // Use configurable timeout (default 30s)
119→    const timeout = timeoutMs && timeoutMs > 0 ? timeoutMs : 30000;
120→
121→    // Use configurable max bytes (default 5MB)
122→    const maxBytesLimit = maxBytes && maxBytes > 0 ? maxBytes : 5 * 1024 * 1024;
123→
124→    // Fetch the page with timeout
125→    let response: Response;
126→    try {
127→      const controller = new AbortController();
128→      const timeoutId = setTimeout(() => controller.abort(), timeout);
129→
130→      response = await fetch(url, {
131→        headers: {
132→          'User-Agent': 'Mozilla/5.0 (compatible; TPMJSBot/1.0; +https://tpmjs.com)',
133→          Accept: 'text/html,application/xhtml+xml,application/xml;q=0.9,text/plain,*/*;q=0.8',
134→        },
135→        signal: controller.signal,
136→      });
137→
138→      clearTimeout(timeoutId);
139→
140→      if (!response.ok) {
141→        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
142→      }
143→    } catch (error) {
144→      if (error instanceof Error) {
145→        if (error.name === 'AbortError') {
146→          throw new Error(`Request to ${url} timed out after ${timeout}ms`);
147→        }
148→        if (error.message.includes('ENOTFOUND') || error.message.includes('getaddrinfo')) {
149→          throw new Error(`DNS resolution failed for ${url}. Check the domain name.`);
150→        }
151→        if (error.message.includes('ECONNREFUSED')) {
152→          throw new Error(`Connection refused to ${url}. The server may be down.`);
153→        }
154→        if (error.message.includes('CERT_')) {
155→          throw new Error(
156→            `SSL certificate error for ${url}. The site may have an invalid certificate.`
157→          );
158→        }
159→        throw new Error(`Failed to fetch URL ${url}: ${error.message}`);
160→      }
161→      throw new Error(`Failed to fetch URL ${url}: Unknown network error`);
162→    }
163→
164→    // Get content type
165→    const contentType = response.headers.get('content-type') || 'unknown';
166→
167→    // Get response text, limiting by maxBytes (default 5MB)
168→    let rawText: string;
169→    if (maxBytesLimit > 0) {
170→      // Read response as stream and limit to maxBytes
171→      const reader = response.body?.getReader();
172→      if (!reader) {
173→        rawText = await response.text();
174→      } else {
175→        const chunks: Uint8Array[] = [];
176→        let totalBytes = 0;
177→        const decoder = new TextDecoder();
178→
179→        while (totalBytes < maxBytesLimit) {
180→          const { done, value } = await reader.read();
181→          if (done) break;
182→          chunks.push(value);
183→          totalBytes += value.length;
184→        }
185→
186→        // Cancel the stream if we hit the limit
187→        if (totalBytes >= maxBytesLimit) {
188→          await reader.cancel();
189→        }
190→
191→        rawText = chunks.map((chunk) => decoder.decode(chunk, { stream: true })).join('');
192→        // Truncate to exactly maxBytesLimit if we went over
193→        if (rawText.length > maxBytesLimit) {
194→          rawText = rawText.slice(0, maxBytesLimit);
195→        }
196→      }
197→    } else {
198→      rawText = await response.text();
199→    }
200→
201→    // Strip HTML tags if content is HTML
202→    let text: string;
203→    if (contentType.includes('text/html') || contentType.includes('application/xhtml')) {
204→      text = stripHtmlTags(rawText);
205→    } else {
206→      text = rawText;
207→    }
208→
209→    const contentLength = rawText.length;
210→
211→    // Build result
212→    const result: FetchResult = {
213→      text,
214→      url,
215→      contentLength,
216→      contentType,
217→      metadata: {
218→        fetchedAt: new Date().toISOString(),
219→        statusCode: response.status,
220→        redirected: response.redirected,
221→        finalUrl: response.url,
222→      },
223→    };
224→
225→    return result;
226→  },
227→});
228→
229→export default fetchTextTool;
230→

  1→/**
  2→ * Executor Resolution Logic
  3→ *
  4→ * Handles the cascade resolution for hot-swappable executors:
  5→ * Agent Config → Collection Config → System Default
  6→ */
  7→
  8→import { executePackage } from '@tpmjs/package-executor';
  9→import type {
 10→  CreateSessionResponse,
 11→  DestroySessionResponse,
 12→  ExecuteToolRequest,
 13→  ExecuteToolResponse,
 14→  ExecutorConfig,
 15→  ExecutorHealthResponse,
 16→  SandboxExecutorConfig,
 17→} from '@tpmjs/types/executor';
 18→
 19→const DEFAULT_TIMEOUT = 300000; // 5 minutes for custom executors
 20→
 21→/**
 22→ * Resolve executor configuration using cascade:
 23→ * Agent Config → Collection Config → System Default
 24→ *
 25→ * @param agentConfig - Executor config from Agent (highest priority)
 26→ * @param collectionConfig - Executor config from Collection (medium priority)
 27→ * @returns Resolved executor configuration
 28→ */
 29→export function resolveExecutorConfig(
 30→  agentConfig: ExecutorConfig | null | undefined,
 31→  collectionConfig: ExecutorConfig | null | undefined
 32→): ExecutorConfig {
 33→  // Agent config takes precedence
 34→  if (agentConfig && agentConfig.type !== 'default') {
 35→    return agentConfig;
 36→  }
 37→
 38→  // Fall back to collection config
 39→  if (collectionConfig && collectionConfig.type !== 'default') {
 40→    return collectionConfig;
 41→  }
 42→
 43→  // System default
 44→  return { type: 'default' };
 45→}
 46→
 47→/**
 48→ * Parse executor config from database JSON
 49→ * Handles null/undefined and validates the shape
 50→ */
 51→export function parseExecutorConfig(
 52→  executorType: string | null | undefined,
 53→  executorConfig: unknown
 54→): ExecutorConfig | null {
 55→  if (!executorType) {
 56→    return null;
 57→  }
 58→
 59→  if (executorType === 'default') {
 60→    return { type: 'default' };
 61→  }
 62→
 63→  if (executorType === 'custom_url' && executorConfig && typeof executorConfig === 'object') {
 64→    const config = executorConfig as { url?: string; apiKey?: string };
 65→    if (config.url && typeof config.url === 'string') {
 66→      return {
 67→        type: 'custom_url',
 68→        url: config.url,
 69→        apiKey: typeof config.apiKey === 'string' ? config.apiKey : undefined,
 70→      };
 71→    }
 72→  }
 73→
 74→  if (executorType === 'sandbox') {
 75→    const config =
 76→      executorConfig && typeof executorConfig === 'object'
 77→        ? (executorConfig as { url?: string; apiKey?: string })
 78→        : {};
 79→    return {
 80→      type: 'sandbox',
 81→      url: typeof config.url === 'string' ? config.url : undefined,
 82→      apiKey: typeof config.apiKey === 'string' ? config.apiKey : undefined,
 83→    };
 84→  }
 85→
 86→  return null;
 87→}
 88→
 89→/**
 90→ * Execute a tool using a custom URL executor
 91→ */
 92→async function executeWithCustomUrl(
 93→  url: string,
 94→  apiKey: string | undefined,
 95→  request: ExecuteToolRequest,
 96→  timeout: number = DEFAULT_TIMEOUT
 97→): Promise<ExecuteToolResponse> {
 98→  const startTime = Date.now();
 99→
100→  const headers: Record<string, string> = {
101→    'Content-Type': 'application/json',
102→  };
103→
104→  if (apiKey) {
105→    headers.Authorization = `Bearer ${apiKey}`;
106→  }
107→
108→  try {
109→    const controller = new AbortController();
110→    const timeoutId = setTimeout(() => controller.abort(), timeout);
111→
112→    const response = await fetch(`${url}/execute-tool`, {
113→      method: 'POST',
114→      headers,
115→      body: JSON.stringify(request),
116→      signal: controller.signal,
117→    });
118→
119→    clearTimeout(timeoutId);
120→
121→    const executionTimeMs = Date.now() - startTime;
122→
123→    if (!response.ok) {
124→      const errorData = (await response.json().catch(() => ({ error: 'Unknown error' }))) as {
125→        error?: string;
126→      };
127→      return {
128→        success: false,
129→        error: errorData.error || `Executor error: ${response.status}`,
130→        executionTimeMs,
131→      };
132→    }
133→
134→    const result = (await response.json()) as ExecuteToolResponse;
135→
136→    return {
137→      success: result.success,
138→      output: result.output,
139→      error: result.error,
140→      executionTimeMs: result.executionTimeMs || executionTimeMs,
141→    };
142→  } catch (error) {
143→    const executionTimeMs = Date.now() - startTime;
144→
145→    if (error instanceof Error && error.name === 'AbortError') {
146→      return {
147→        success: false,
148→        error: 'Execution timeout',
149→        executionTimeMs,
150→      };
151→    }
152→
153→    return {
154→      success: false,
155→      error: error instanceof Error ? error.message : String(error),
156→      executionTimeMs,
157→    };
158→  }
159→}
