195→/**
196→ * Parse environment variables from JSON field
197→ * Returns empty object if null/undefined or invalid
198→ */
199→function parseEnvVars(envVars: unknown): Record<string, string> {
200→  if (!envVars || typeof envVars !== 'object') {
201→    return {};
202→  }
203→  // Validate all values are strings
204→  const result: Record<string, string> = {};
205→  for (const [key, value] of Object.entries(envVars)) {
206→    if (typeof value === 'string') {
207→      result[key] = value;
208→    }
209→  }
210→  return result;
211→}
212→
213→/**
214→ * Merge environment variables with agent envVars taking precedence
215→ * Collection envVars are used as base, agent envVars override
216→ */
217→function mergeEnvVars(
218→  collectionEnvVars: Record<string, string>,
219→  agentEnvVars: Record<string, string>
220→): Record<string, string> {
221→  return {
222→    ...collectionEnvVars,
223→    ...agentEnvVars, // Agent overrides collection
224→  };
225→}
226→
227→/**
228→ * Build all tools from an agent's collections and individual tools
229→ * Returns a map of tool name -> AI SDK tool definition
230→ *
231→ * Executor config cascade: Agent → Collection → System Default
232→ * - If agent has an executor config, it's used for all tools
233→ * - If agent has no config but collection has one, collection's config is used for tools from that collection
234→ * - If neither has config, system default is used
235→ *
236→ * Environment variables cascade: Agent → Collection (merged, agent overrides)
237→ * - Collection env vars are used as base
238→ * - Agent env vars override collection env vars for same keys
239→ * - Both are merged together for unique keys
240→ *
241→ * @param agent - The agent with tool relations
242→ * @param callerEnvVars - Optional env vars provided by the caller (for non-owners accessing public agents).
243→ *                        When provided, these are used INSTEAD of the agent's stored env vars.
244→ * @param sessionId - Optional session ID for sandbox executors
245→ */
246→export function buildAgentTools(
247→  agent: AgentWithRelations,
248→  callerEnvVars?: Record<string, string>,
249→  sessionId?: string
250→): Record<string, ReturnType<typeof createToolDefinition>> {
251→  const tools: Record<string, ReturnType<typeof createToolDefinition>> = {};
252→  const seenTools = new Set<string>();
253→
254→  // Parse agent-level executor config
255→  const agentExecutorConfig = parseExecutorConfig(agent.executorType, agent.executorConfig);
256→
257→  // When callerEnvVars is provided (non-owner using public agent), use those exclusively.
258→  // Otherwise, use the agent's stored env vars.
259→  const useCallerEnvVars = callerEnvVars !== undefined;
260→  const agentEnvVars = useCallerEnvVars ? callerEnvVars : parseEnvVars(agent.envVars);
261→
262→  // Add tools from collections first
263→  for (const agentCollection of agent.collections) {
264→    const collection = agentCollection.collection;
265→
266→    // Parse collection-level executor config
267→    const collectionExecutorConfig = parseExecutorConfig(
268→      collection.executorType,
269→      collection.executorConfig
270→    );
271→
272→    // Resolve executor config: Agent → Collection → Default
273→    const resolvedConfig = resolveExecutorConfig(agentExecutorConfig, collectionExecutorConfig);
274→
275→    // Parse collection-level env vars and merge with agent env vars
276→    // When callerEnvVars is provided, skip collection env vars entirely
277→    const collectionEnvVars = useCallerEnvVars ? {} : parseEnvVars(collection.envVars);
278→    const mergedEnvVars = mergeEnvVars(collectionEnvVars, agentEnvVars);
279→
280→    for (const collectionTool of collection.tools) {
281→      const tool = collectionTool.tool;
282→      const toolKey = `${tool.package.npmPackageName}::${tool.name}`;
283→
284→      // Avoid duplicates
285→      if (seenTools.has(toolKey)) continue;
286→      seenTools.add(toolKey);
287→
288→      const toolName = sanitizeToolName(`${tool.package.npmPackageName}-${tool.name}`);
289→      tools[toolName] = createToolDefinition(tool, resolvedConfig, mergedEnvVars, sessionId);
290→    }
291→  }
292→
293→  // Add individual tools (may override collection tools)
294→  // Individual tools use agent config or system default (no collection context)
295→  // Individual tools only use agent env vars (no collection context)
296→  const individualToolConfig = agentExecutorConfig ?? { type: 'default' as const };
297→
298→  for (const agentTool of agent.tools) {
299→    const tool = agentTool.tool;
300→    const toolKey = `${tool.package.npmPackageName}::${tool.name}`;
301→
302→    // Skip if already added from collections
303→    if (seenTools.has(toolKey)) continue;
304→    seenTools.add(toolKey);
305→
306→    const toolName = sanitizeToolName(`${tool.package.npmPackageName}-${tool.name}`);
307→    tools[toolName] = createToolDefinition(tool, individualToolConfig, agentEnvVars, sessionId);
308→  }
309→
310→  return tools;
311→}
312→
313→/**
314→ * Get list of tool names for an agent (for display)
315→ */
316→export function getAgentToolNames(agent: AgentWithRelations): string[] {
317→  const names: string[] = [];
318→  const seenTools = new Set<string>();
319→
320→  for (const agentCollection of agent.collections) {
321→    for (const collectionTool of agentCollection.collection.tools) {
322→      const tool = collectionTool.tool;
323→      const toolKey = `${tool.package.npmPackageName}::${tool.name}`;
324→      if (!seenTools.has(toolKey)) {
325→        seenTools.add(toolKey);
326→        names.push(sanitizeToolName(`${tool.package.npmPackageName}-${tool.name}`));
327→      }
328→    }
329→  }
330→
331→  for (const agentTool of agent.tools) {
332→    const tool = agentTool.tool;
333→    const toolKey = `${tool.package.npmPackageName}::${tool.name}`;
334→    if (!seenTools.has(toolKey)) {
335→      seenTools.add(toolKey);
336→      names.push(sanitizeToolName(`${tool.package.npmPackageName}-${tool.name}`));
337→    }
338→  }
339→
340→  return names;
341→}
