  2→ * AI Agent service for executing TPMJS tools
  3→ * Converts TPMJS metadata to Zod schemas and executes with AI SDK v6
  4→ */
  5→
  6→import { openai } from '@ai-sdk/openai';
  7→import type { Package, Tool } from '@tpmjs/db';
  8→import type { ExecutorConfig } from '@tpmjs/types/executor';
  9→import { generateText, jsonSchema, type ModelMessage } from 'ai';
 10→import { z } from 'zod';
 11→
 12→import { executeWithExecutor } from '../executors';
 13→
 14→/**
 15→ * Parameter from TPMJS metadata
 16→ */
 17→interface TPMJSParameter {
 18→  name: string;
 19→  type: string;
 20→  required: boolean;
 21→  description: string;
 22→  default?: unknown;
 23→}
 24→
 25→/**
 26→ * Token usage breakdown
 27→ */
 28→export interface TokenBreakdown {
 29→  inputTokens: number;
 30→  toolDescTokens: number;
 31→  schemaTokens: number;
 32→  outputTokens: number;
 33→  totalTokens: number;
 34→  estimatedCost: number;
 35→}
 36→
 37→/**
 38→ * Convert TPMJS parameter type to Zod schema
 39→ */
 40→function typeToZodSchema(type: string): z.ZodTypeAny {
 41→  // Handle array types
 42→  if (type.endsWith('[]')) {
 43→    const baseType = type.slice(0, -2);
 44→    return z.array(typeToZodSchema(baseType));
 45→  }
 46→
 47→  // Handle union types (e.g., 'markdown' | 'mdx')
 48→  if (type.includes('|')) {
 49→    const types = type.split('|').map((t) => t.trim().replace(/'/g, ''));
 50→    return z.enum(types as [string, ...string[]]);
 51→  }
 52→
 53→  // Handle primitive types
 54→  switch (type) {
 55→    case 'string':
 56→      return z.string();
 57→    case 'number':
 58→      return z.number();
 59→    case 'boolean':
 60→      return z.boolean();
 61→    case 'object':
 62→      return z.object({});
 63→    default:
 64→      // Default to string for unknown types
 65→      return z.string();
 66→  }
 67→}
 68→
 69→/**
 70→ * Convert TPMJS parameters to Zod schema object
 71→ */
 72→// biome-ignore lint/suspicious/noExplicitAny: Zod requires any for dynamic schema objects
 73→export function tpmjsParamsToZodSchema(parameters: TPMJSParameter[]): z.ZodObject<any> {
 74→  const shape: Record<string, z.ZodTypeAny> = {};
 75→
 76→  for (const param of parameters) {
 77→    let schema = typeToZodSchema(param.type);
 78→
 79→    // Add description
 80→    schema = schema.describe(param.description);
 81→
 82→    // Make optional if not required
 83→    if (!param.required) {
 84→      schema = schema.optional();
 85→    }
 86→
 87→    shape[param.name] = schema;
 88→  }
 89→
 90→  return z.object(shape);
 91→}
 92→
 93→/**
 94→ * Create AI SDK v6 tool definition from TPMJS Tool
 95→ * Requires Tool with Package relation
 96→ *
 97→ * @param tool - The tool with its package relation
 98→ * @param executorConfig - Optional executor config for custom executors
 99→ * @param envVars - Optional environment variables to pass to the tool
100→ * @param sessionId - Optional session ID for sandbox executors
101→ */
102→export function createToolDefinition(
103→  tool: Tool & { package: Package },
104→  executorConfig?: ExecutorConfig | null,
105→  envVars?: Record<string, string>,
106→  sessionId?: string
107→) {
108→  console.log('[createToolDefinition] Tool:', tool.package.npmPackageName, '/', tool.name);
109→
110→  // Prefer full inputSchema if available (has nested object/array structures)
111→  // Fall back to legacy parameters array conversion if not
112→  const inputSchema =
113→    tool.inputSchema && typeof tool.inputSchema === 'object'
114→      ? // Use full JSON Schema directly - preserves nested array/object structures
115→        jsonSchema(tool.inputSchema as Parameters<typeof jsonSchema>[0])
116→      : // Legacy: convert flattened parameters array to Zod schema
117→        (() => {
118→          const parameters = Array.isArray(tool.parameters)
119→            ? (tool.parameters as unknown as TPMJSParameter[])
120→            : [];
121→          console.log('[createToolDefinition] Using legacy parameters:', parameters.length);
122→          return parameters.length > 0
123→            ? tpmjsParamsToZodSchema(parameters)
124→            : z.object({}).describe('No parameters required');
125→        })();
126→
127→  const sanitizedName = sanitizeToolName(`${tool.package.npmPackageName}-${tool.name}`);
128→
129→  // AI SDK v6 tool definition
130→  return {
131→    description: tool.description,
132→    inputSchema, // AI SDK v6 uses inputSchema
133→    execute: async (params: Record<string, unknown>) => {
134→      console.log('[Tool execute] Running:', sanitizedName, params);
135→      if (envVars && Object.keys(envVars).length > 0) {
136→        console.log('[Tool execute] With env vars:', Object.keys(envVars));
137→      }
138→
139→      // Execute the actual npm package using resolved executor
140→      // Use the actual export name from the Tool record
141→      // Pass explicit version to avoid Deno HTTP import cache issues with @latest
142→      const result = await executeWithExecutor(
143→        executorConfig ?? null,
144→        {
145→          packageName: tool.package.npmPackageName,
146→          name: tool.name, // Use actual export name (e.g., "helloWorldTool", "default")
147→          version: tool.package.npmVersion,
148→          params,
149→          env: envVars && Object.keys(envVars).length > 0 ? envVars : undefined,
150→        },
151→        sessionId
152→      );
153→
154→      if (!result.success) {
155→        // Log detailed error for debugging
156→        console.error('[Tool execute] FAILED:', sanitizedName, {
157→          error: result.error,
158→          executionTimeMs: result.executionTimeMs,
159→          params: JSON.stringify(params).slice(0, 200),
160→        });
161→        throw new Error(result.error || 'Package execution failed');
162→      }
163→
164→      console.log('[Tool execute] Success:', sanitizedName, {
165→        executionTimeMs: result.executionTimeMs,
166→        outputPreview: JSON.stringify(result.output).slice(0, 200),
167→      });
168→      return result.output;
169→    },
170→  };
171→}
