 153→// ============================================================================
 154→// Sandbox Connection Cache
 155→// ============================================================================
 156→
 157→const sandboxCache = new Map<string, Sandbox>();
 158→
 159→async function getOrConnectSandbox(sandboxId: string): Promise<Sandbox> {
 160→  if (!sandboxId) {
 161→    throw new Error('sandboxId is required');
 162→  }
 163→
 164→  const cached = sandboxCache.get(sandboxId);
 165→  if (cached) {
 166→    return cached;
 167→  }
 168→
 169→  try {
 170→    const sandbox = await Sandbox.connect(sandboxId);
 171→    sandboxCache.set(sandboxId, sandbox);
 172→    return sandbox;
 173→  } catch (error) {
 174→    const message = error instanceof Error ? error.message : 'Unknown error';
 175→    throw new Error(`Failed to connect to sandbox ${sandboxId}: ${message}`);
 176→  }
 177→}
 178→
 179→function removeSandboxFromCache(sandboxId: string): void {
 180→  sandboxCache.delete(sandboxId);
 181→}
