 187→/**
 188→ * Create a new E2B sandbox
 189→ */
 190→export const createSandbox = tool({
 191→  description:
 192→    'Create a new E2B cloud sandbox from a template. Sandboxes are isolated Linux environments for AI code execution. Defaults to "base" template with 5 minute timeout if not specified. Requires E2B_API_KEY.',
 193→  inputSchema: jsonSchema<CreateSandboxInput>({
 194→    type: 'object',
 195→    properties: {
 196→      template: {
 197→        type: 'string',
 198→        description: 'Template ID to use (default: "base" for Code Interpreter)',
 199→      },
 200→      timeoutMs: {
 201→        type: 'number',
 202→        description: 'Sandbox timeout in milliseconds (default: 300000 = 5 minutes)',
 203→      },
 204→      metadata: {
 205→        type: 'object',
 206→        description: 'Custom metadata key-value pairs to attach to sandbox',
 207→        additionalProperties: { type: 'string' },
 208→      },
 209→      envVars: {
 210→        type: 'object',
 211→        description: 'Environment variables to set in the sandbox',
 212→        additionalProperties: { type: 'string' },
 213→      },
 214→    },
 215→    required: [],
 216→    additionalProperties: false,
 217→  }),
 218→  async execute(input: CreateSandboxInput): Promise<E2BSandbox> {
 219→    const templateId = input.template || 'base';
 220→    const timeoutMs = input.timeoutMs || 300000; // Default 5 minutes
 221→
 222→    try {
 223→      const sandbox = await Sandbox.create(templateId, {
 224→        timeoutMs,
 225→        metadata: input.metadata,
 226→        envs: input.envVars,
 227→      });
 228→
 229→      sandboxCache.set(sandbox.sandboxId, sandbox);
 230→
 231→      return {
 232→        sandboxId: sandbox.sandboxId,
 233→        templateId,
 234→        status: 'running',
 235→        startedAt: new Date().toISOString(),
 236→        clientId: sandbox.sandboxId,
 237→        metadata: input.metadata,
 238→      };
 239→    } catch (error) {
 240→      const message = error instanceof Error ? error.message : 'Unknown error';
 241→      throw new Error(`Failed to create sandbox with template "${templateId}": ${message}`);
 242→    }
 243→  },
 244→});
