 431→ */
 432→export const runCommand = tool({
 433→  description:
 434→    'Execute a shell command in an E2B sandbox with full shell access. Supports background processes and working directory. Requires E2B_API_KEY.',
 435→  inputSchema: jsonSchema<RunCommandInput>({
 436→    type: 'object',
 437→    properties: {
 438→      sandboxId: {
 439→        type: 'string',
 440→        description: 'ID of the sandbox',
 441→      },
 442→      command: {
 443→        type: 'string',
 444→        description: 'Shell command to execute',
 445→      },
 446→      cwd: {
 447→        type: 'string',
 448→        description: 'Working directory for the command',
 449→      },
 450→      background: {
 451→        type: 'boolean',
 452→        description: 'Run command in background (default: false)',
 453→      },
 454→      timeoutMs: {
 455→        type: 'number',
 456→        description: 'Command timeout in milliseconds (default: 60000)',
 457→      },
 458→    },
 459→    required: ['sandboxId', 'command'],
 460→    additionalProperties: false,
 461→  }),
 462→  async execute(
 463→    input: RunCommandInput
 464→  ): Promise<{ stdout: string; stderr: string; exitCode: number; processId?: string }> {
 465→    const timeoutMs = input.timeoutMs || 60000;
 466→
 467→    try {
 468→      const sandbox = await getOrConnectSandbox(input.sandboxId);
 469→
 470→      if (input.background) {
 471→        const process = await sandbox.commands.run(input.command, {
 472→          cwd: input.cwd,
 473→          background: true,
 474→          timeoutMs,
 475→        });
 476→        return {
 477→          stdout: '',
 478→          stderr: '',
 479→          exitCode: 0,
 480→          processId: String(process.pid),
 481→        };
 482→      }
 483→
 484→      const result = await sandbox.commands.run(input.command, {
 485→        cwd: input.cwd,
 486→        timeoutMs,
 487→      });
 488→
 489→      return {
 490→        stdout: result.stdout,
 491→        stderr: result.stderr,
 492→        exitCode: result.exitCode,
 493→      };
 494→    } catch (error) {
 495→      const message = error instanceof Error ? error.message : 'Unknown error';
 496→      throw new Error(`Failed to run command in sandbox ${input.sandboxId}: ${message}`);
 497→    }
 498→  },
 499→});
