 620→  inputSchema: jsonSchema<UploadFileInput>({
 621→    type: 'object',
 622→    properties: {
 623→      sandboxId: {
 624→        type: 'string',
 625→        description: 'ID of the sandbox',
 626→      },
 627→      path: {
 628→        type: 'string',
 629→        description: 'Destination path in sandbox',
 630→      },
 631→      content: {
 632→        type: 'string',
 633→        description: 'Base64 encoded file content',
 634→      },
