 671→/**
 672→ * Download file from sandbox
 673→ */
 674→export const downloadFile = tool({
 675→  description: 'Download a file from the E2B sandbox as base64 content. Requires E2B_API_KEY.',
 676→  inputSchema: jsonSchema<DownloadFileInput>({
 677→    type: 'object',
 678→    properties: {
 679→      sandboxId: {
 680→        type: 'string',
 681→        description: 'ID of the sandbox',
 682→      },
 683→      path: {
 684→        type: 'string',
 685→        description: 'Path to file in sandbox',
 686→      },
 687→    },
 688→    required: ['sandboxId', 'path'],
 689→    additionalProperties: false,
 690→  }),
 691→  async execute(
 692→    input: DownloadFileInput
 693→  ): Promise<{ content: string; filename: string; size: number; mimeType: string }> {
 694→    const sandbox = await getOrConnectSandbox(input.sandboxId);
 695→    const content = await sandbox.files.read(input.path);
 696→
 697→    const filename = input.path.split('/').pop() || 'file';
 698→    const ext = filename.split('.').pop()?.toLowerCase() || '';
 699→
 700→    // Convert to base64 and calculate size
 701→    let base64Content: string;
 702→    let contentLength: number;
 703→
 704→    if (typeof content === 'string') {
 705→      base64Content = btoa(content);
 706→      contentLength = content.length;
 707→    } else {
 708→      const bytes = new Uint8Array(content as ArrayBuffer);
 709→      contentLength = bytes.length;
 710→      let binary = '';
 711→      for (let i = 0; i < bytes.length; i++) {
 712→        binary += String.fromCharCode(bytes[i] as number);
 713→      }
 714→      base64Content = btoa(binary);
 715→    }
 716→
 717→    // Simple MIME type detection
 718→    const mimeTypes: Record<string, string> = {
 719→      txt: 'text/plain',
 720→      json: 'application/json',
 721→      js: 'text/javascript',
 722→      ts: 'text/typescript',
 723→      py: 'text/x-python',
 724→      html: 'text/html',
 725→      css: 'text/css',
 726→      png: 'image/png',
 727→      jpg: 'image/jpeg',
 728→      jpeg: 'image/jpeg',
 729→      gif: 'image/gif',
 730→      pdf: 'application/pdf',
 731→      zip: 'application/zip',
 732→    };
 733→
 734→    return {
 735→      content: base64Content,
 736→      filename,
 737→      size: contentLength,
 738→      mimeType: mimeTypes[ext] || 'application/octet-stream',
 739→    };
 740→  },
 741→});
