 889→ */
 890→export const setEnvVars = tool({
 891→  description:
 892→    'Set environment variables in an E2B sandbox. These persist for subsequent code executions in the same sandbox session. Special characters are safely escaped. Requires E2B_API_KEY.',
 893→  inputSchema: jsonSchema<SetEnvVarsInput>({
 894→    type: 'object',
 895→    properties: {
 896→      sandboxId: {
 897→        type: 'string',
 898→        description: 'ID of the sandbox',
 899→      },
 900→      envVars: {
 901→        type: 'object',
 902→        description: 'Key-value pairs of environment variables to set',
 903→        additionalProperties: { type: 'string' },
 904→      },
 905→    },
 906→    required: ['sandboxId', 'envVars'],
 907→    additionalProperties: false,
 908→  }),
 909→  async execute(input: SetEnvVarsInput): Promise<{ success: boolean; count: number }> {
 910→    try {
 911→      const sandbox = await getOrConnectSandbox(input.sandboxId);
 912→
 913→      // Escape shell special characters in values
 914→      const escapeForShell = (str: string): string => {
 915→        return str
 916→          .replace(/\\/g, '\\\\')
 917→          .replace(/"/g, '\\"')
 918→          .replace(/\$/g, '\\$')
 919→          .replace(/`/g, '\\`')
 920→          .replace(/!/g, '\\!');
 921→      };
 922→
 923→      // Set each environment variable using shell export
 924→      for (const [key, value] of Object.entries(input.envVars)) {
 925→        await sandbox.commands.run(`export ${key}="${escapeForShell(value)}"`);
 926→      }
 927→
 928→      return { success: true, count: Object.keys(input.envVars).length };
 929→    } catch (error) {
 930→      const message = error instanceof Error ? error.message : 'Unknown error';
 931→      throw new Error(
 932→        `Failed to set environment variables in sandbox ${input.sandboxId}: ${message}`
 933→      );
 934→    }
 935→  },
 936→});
