 941→export const getMetrics = tool({
 942→  description:
 943→    'Get resource usage metrics for an E2B sandbox including CPU, memory, and network usage. Requires E2B_API_KEY.',
 944→  inputSchema: jsonSchema<SandboxIdInput>({
 945→    type: 'object',
