  1→/**
  2→ * @tpmjs/tools-discord — Discord API Tools for AI Agents
  3→ *
  4→ * Full access to the Discord REST API: send messages, manage channels, guilds,
  5→ * members, threads, reactions, and more.
  6→ *
  7→ * @requires DISCORD_BOT_TOKEN environment variable
  8→ */
  9→
 10→import { jsonSchema, tool } from 'ai';
 11→
 12→const BASE_URL = 'https://discord.com/api/v10';
 13→
 14→// ─── Client Infrastructure ──────────────────────────────────────────────────
 15→
 16→function getApiKey(): string {
 17→  const key = process.env.DISCORD_BOT_TOKEN;
 18→  if (!key) {
 19→    throw new Error(
 20→      'DISCORD_BOT_TOKEN environment variable is required. Get your token from https://discord.com/developers/applications'
 21→    );
 22→  }
 23→  return key;
 24→}
 25→
 26→async function apiRequest<T>(method: string, path: string, body?: unknown): Promise<T> {
 27→  const key = getApiKey();
 28→
 29→  const headers: Record<string, string> = {
 30→    Authorization: `Bot ${key}`,
 31→    'Content-Type': 'application/json',
 32→  };
 33→
 34→  const options: RequestInit = { method, headers };
 35→  if (body !== undefined) {
 36→    options.body = JSON.stringify(body);
 37→  }
 38→
 39→  const response = await fetch(`${BASE_URL}${path}`, options);
 40→
 41→  if (!response.ok) {
 42→    await handleApiError(response);
 43→  }
 44→
 45→  if (response.status === 204) {
 46→    return { success: true } as T;
 47→  }
 48→
 49→  const text = await response.text();
 50→  if (!text) {
 51→    return {} as T;
 52→  }
 53→
 54→  return JSON.parse(text) as T;
 55→}
 56→
 57→async function handleApiError(response: Response): Promise<never> {
 58→  let errorMessage: string;
 59→  try {
 60→    const errorData = (await response.json()) as { message?: string; code?: number };
 61→    errorMessage = errorData.message || `HTTP ${response.status}`;
 62→    if (errorData.code) {
 63→      errorMessage = `${errorMessage} (Discord Error Code: ${errorData.code})`;
 64→    }
 65→  } catch {
 66→    errorMessage = `HTTP ${response.status}: ${response.statusText}`;
 67→  }
 68→
 69→  switch (response.status) {
 70→    case 400:
 71→      throw new Error(`Bad request: ${errorMessage}`);
 72→    case 401:
 73→      throw new Error('Authentication failed: Invalid Discord bot token. Check DISCORD_BOT_TOKEN.');
 74→    case 403:
 75→      throw new Error(`Access forbidden: ${errorMessage}`);
 76→    case 404:
 77→      throw new Error(`Not found: ${errorMessage}`);
 78→    case 429:
 79→      throw new Error(`Rate limit exceeded: ${errorMessage}`);
 80→    default:
 81→      throw new Error(`Discord API error (${response.status}): ${errorMessage}`);
 82→  }
 83→}
 84→
 85→function buildQueryString(params: Record<string, unknown>): string {
 86→  const entries = Object.entries(params).filter(
 87→    ([, v]) => v !== undefined && v !== null && v !== ''
 88→  );
 89→  if (entries.length === 0) return '';
 90→  return (
 91→    '?' +
 92→    entries.map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`).join('&')
 93→  );
 94→}
 95→
 96→// ─── Output Types ────────────────────────────────────────────────────────────
 97→
 98→export interface DiscordMessage {
 99→  id: string;
100→  channel_id: string;
101→  content: string;
102→  author: { id: string; username: string; discriminator: string };
103→  timestamp: string;
104→  tts: boolean;
105→  pinned: boolean;
106→}
107→
108→export interface DiscordGuild {
109→  id: string;
110→  name: string;
111→  icon: string | null;
112→  owner_id: string;
113→  member_count?: number;
114→  approximate_member_count?: number;
115→  approximate_presence_count?: number;
116→  features: string[];
117→}
118→
119→export interface DiscordChannel {
120→  id: string;
121→  type: number;
122→  guild_id?: string;
123→  name?: string;
124→  topic?: string | null;
125→  position?: number;
126→  parent_id?: string | null;
127→}
128→
129→export interface DiscordMember {
130→  user: { id: string; username: string; discriminator: string };
131→  nick: string | null;
132→  roles: string[];
133→  joined_at: string;
134→}
135→
136→export interface DiscordThread {
137→  id: string;
138→  name: string;
139→  type: number;
140→  guild_id: string;
141→  parent_id: string;
142→  owner_id: string;
143→  message_count: number;
144→  member_count: number;
145→}
146→
147→export interface SuccessResult {
148→  success: boolean;
149→}
150→
151→export interface ListThreadsResult {
152→  threads: DiscordThread[];
153→  members: { id: string; user_id: string; join_timestamp: string }[];
154→}
155→
156→// ─── Messages ───────────────────────────────────────────────────────────────
157→
158→export interface SendMessageInput {
159→  channel_id: string;
160→  content: string;
161→  tts?: boolean;
162→}
163→
164→export const sendMessage = tool({
165→  description: 'Send a message to a Discord channel with optional text-to-speech.',
166→  inputSchema: jsonSchema<SendMessageInput>({
167→    type: 'object',
168→    properties: {
169→      channel_id: { type: 'string', description: 'The ID of the channel to send the message to.' },
170→      content: { type: 'string', description: 'The message content (up to 2000 characters).' },
171→      tts: {
172→        type: 'boolean',
173→        description: 'Whether this message should be sent as text-to-speech.',
174→      },
175→    },
176→    required: ['channel_id', 'content'],
177→    additionalProperties: false,
178→  }),
179→  async execute(input: SendMessageInput): Promise<DiscordMessage> {
180→    try {
181→      if (!input.channel_id || !input.content) {
182→        throw new Error('channel_id and content are required and must be non-empty');
183→      }
184→      if (input.content.length > 2000) {
185→        throw new Error('Message content must be 2000 characters or less');
186→      }
187→      return await apiRequest<DiscordMessage>('POST', `/channels/${input.channel_id}/messages`, {
188→        content: input.content,
189→        tts: input.tts,
190→      });
191→    } catch (error) {
192→      throw new Error(`Failed to send message: ${(error as Error).message}`);
193→    }
194→  },
195→});
