214→        description: 'Number of messages to retrieve (1-100, default: 50).',
215→      },
216→      before: { type: 'string', description: 'Get messages before this message ID.' },
217→      after: { type: 'string', description: 'Get messages after this message ID.' },
218→      around: { type: 'string', description: 'Get messages around this message ID.' },
219→    },
220→    required: ['channel_id'],
221→    additionalProperties: false,
222→  }),
223→  async execute(input: ListMessagesInput): Promise<DiscordMessage[]> {
224→    try {
225→      if (!input.channel_id) {
226→        throw new Error('channel_id is required');
227→      }
228→      if (input.limit !== undefined && (input.limit < 1 || input.limit > 100)) {
