  1→/**
  2→ * Sprites Exec Tool for TPMJS
  3→ * Executes a command inside a sprite and returns the output.
  4→ * Supports stdin input for interactive commands.
  5→ *
  6→ * @requires SPRITES_TOKEN environment variable
  7→ */
  8→
  9→import { jsonSchema, tool } from 'ai';
 10→
 11→const SPRITES_API_BASE = 'https://api.sprites.dev/v1';
 12→
 13→// Binary stream IDs from Sprites API
 14→const STREAM_STDIN = 0x00;
 15→const STREAM_STDOUT = 0x01;
 16→const STREAM_STDERR = 0x02;
 17→const STREAM_EXIT = 0x03;
 18→
 19→export interface ExecResult {
 20→  exitCode: number;
 21→  stdout: string;
 22→  stderr: string;
 23→  duration: number;
 24→}
 25→
 26→type SpritesExecInput = {
 27→  name: string;
 28→  cmd: string;
 29→  stdin?: string;
 30→  timeoutMs?: number;
 31→};
 32→
 33→function getSpritesToken(): string {
 34→  const token = process.env.SPRITES_TOKEN;
 35→  if (!token) {
 36→    throw new Error(
 37→      'SPRITES_TOKEN environment variable is required. Get your token from https://sprites.dev'
 38→    );
 39→  }
 40→  return token;
 41→}
 42→
 43→/**
 44→ * Shell operators that require wrapping the command in sh -c
 45→ */
 46→const SHELL_OPERATORS = ['&&', '||', '|', ';', '>', '>>', '<', '<<', '2>', '2>>', '&>', '$(', '`'];
 47→
 48→/**
 49→ * Check if a command string contains shell operators that need sh -c wrapping
 50→ */
 51→function needsShellWrapper(cmdString: string): boolean {
 52→  // Check for shell operators outside of quotes
 53→  let inSingleQuote = false;
 54→  let inDoubleQuote = false;
 55→
 56→  for (let i = 0; i < cmdString.length; i++) {
 57→    const char = cmdString[i];
 58→
 59→    if (char === "'" && !inDoubleQuote) {
 60→      inSingleQuote = !inSingleQuote;
 61→      continue;
 62→    }
 63→
 64→    if (char === '"' && !inSingleQuote) {
 65→      inDoubleQuote = !inDoubleQuote;
 66→      continue;
 67→    }
 68→
 69→    // Only check for operators when not inside quotes
 70→    if (!inSingleQuote && !inDoubleQuote) {
 71→      for (const op of SHELL_OPERATORS) {
 72→        if (cmdString.slice(i, i + op.length) === op) {
 73→          return true;
 74→        }
 75→      }
 76→    }
 77→  }
 78→
 79→  return false;
 80→}
 81→
 82→/**
 83→ * Parse a command string into command and arguments.
 84→ * Handles quoted strings and escapes.
 85→ * If the command contains shell operators (&&, ||, |, ;, etc.),
 86→ * wraps it in sh -c to execute properly.
 87→ */
 88→function parseCommand(cmdString: string): string[] {
 89→  // If command contains shell operators, wrap in sh -c
 90→  if (needsShellWrapper(cmdString)) {
 91→    return ['sh', '-c', cmdString];
 92→  }
 93→
 94→  const args: string[] = [];
 95→  let current = '';
 96→  let inSingleQuote = false;
 97→  let inDoubleQuote = false;
 98→  let escaped = false;
 99→
100→  for (let i = 0; i < cmdString.length; i++) {
101→    const char = cmdString[i];
102→
103→    if (escaped) {
104→      current += char;
105→      escaped = false;
106→      continue;
107→    }
108→
109→    if (char === '\\' && !inSingleQuote) {
110→      escaped = true;
111→      continue;
112→    }
113→
114→    if (char === "'" && !inDoubleQuote) {
115→      inSingleQuote = !inSingleQuote;
116→      continue;
117→    }
118→
119→    if (char === '"' && !inSingleQuote) {
120→      inDoubleQuote = !inDoubleQuote;
121→      continue;
122→    }
123→
124→    if (char === ' ' && !inSingleQuote && !inDoubleQuote) {
125→      if (current.length > 0) {
126→        args.push(current);
127→        current = '';
128→      }
129→      continue;
130→    }
131→
132→    current += char;
133→  }
134→
135→  if (current.length > 0) {
136→    args.push(current);
137→  }
138→
139→  return args;
140→}
141→
142→/**
143→ * Parse the binary response from Sprites API.
144→ * Format: [stream_id: 1 byte][payload: rest until next stream_id or end]
145→ */
146→function parseBinaryResponse(buffer: Uint8Array): {
147→  stdout: string;
148→  stderr: string;
149→  exitCode: number;
150→} {
151→  let stdout = '';
152→  let stderr = '';
153→  let exitCode = 0;
154→
155→  const decoder = new TextDecoder();
156→  let i = 0;
157→
158→  while (i < buffer.length) {
159→    const streamId = buffer[i];
160→    i++;
161→
162→    if (streamId === STREAM_EXIT) {
163→      // Exit code is a single byte
164→      if (i < buffer.length) {
165→        exitCode = buffer[i] as number;
166→        i++;
167→      }
168→      continue;
169→    }
170→
171→    // Find the next stream marker or end of buffer
172→    let end = i;
173→    while (end < buffer.length) {
174→      const nextByte = buffer[end] as number;
175→      // Check if this looks like a stream ID (0x00-0x03) at a boundary
176→      // We detect boundaries by looking for stream IDs that make sense
177→      if (nextByte <= STREAM_EXIT) {
178→        // Look ahead to see if this is really a stream marker
179→        // Stream markers are followed by data or another marker
180→        break;
181→      }
182→      end++;
183→    }
184→
185→    const payload = decoder.decode(buffer.slice(i, end));
186→
187→    switch (streamId) {
188→      case STREAM_STDIN:
189→        // Ignore stdin echo
190→        break;
191→      case STREAM_STDOUT:
192→        stdout += payload;
193→        break;
194→      case STREAM_STDERR:
195→        stderr += payload;
196→        break;
197→    }
198→
199→    i = end;
200→  }
201→
202→  return { stdout, stderr, exitCode };
203→}
204→
205→export const spritesExecTool = tool({
206→  description:
207→    'Execute a command inside a sprite and return the output. Supports stdin input for interactive commands. Returns exit code, stdout, stderr, and execution duration. IMPORTANT: If starting a web server, it must listen on port 8080 - this is the Sprites convention for public URLs (use sprites-url-set to make it publicly accessible).',
208→  inputSchema: jsonSchema<SpritesExecInput>({
209→    type: 'object',
210→    properties: {
211→      name: {
212→        type: 'string',
213→        description: 'Name of the sprite to execute command in',
214→      },
215→      cmd: {
216→        type: 'string',
217→        description: "Command to execute (e.g., 'ls -la', 'python script.py')",
218→      },
219→      stdin: {
220→        type: 'string',
221→        description: 'Optional stdin input to pass to the command',
222→      },
223→      timeoutMs: {
224→        type: 'number',
225→        description: 'Execution timeout in milliseconds (default: 60000)',
226→      },
227→    },
228→    required: ['name', 'cmd'],
229→    additionalProperties: false,
230→  }),
231→  async execute({ name, cmd, stdin, timeoutMs }): Promise<ExecResult> {
232→    if (!name || typeof name !== 'string') {
233→      throw new Error('Sprite name is required and must be a string');
234→    }
235→    if (!cmd || typeof cmd !== 'string') {
236→      throw new Error('Command is required and must be a string');
237→    }
238→
239→    const token = getSpritesToken();
240→    const timeout = timeoutMs || 60000;
241→    const startTime = Date.now();
242→
243→    // Parse command into parts
244→    const cmdParts = parseCommand(cmd);
245→    if (cmdParts.length === 0) {
246→      throw new Error('Command cannot be empty');
247→    }
248→
249→    // Build URL with repeatable cmd query parameters
250→    // API expects: ?cmd=echo&cmd=hello&cmd=world for "echo hello world"
251→    const url = new URL(`${SPRITES_API_BASE}/sprites/${encodeURIComponent(name)}/exec`);
252→    for (const part of cmdParts) {
253→      url.searchParams.append('cmd', part);
254→    }
255→
256→    // Add stdin flag if stdin is provided
257→    if (stdin) {
258→      url.searchParams.set('stdin', 'true');
259→    }
260→
261→    let response: Response;
262→    try {
263→      const controller = new AbortController();
264→      const timeoutId = setTimeout(() => controller.abort(), timeout);
265→
266→      response = await fetch(url.toString(), {
267→        method: 'POST',
268→        headers: {
269→          Authorization: `Bearer ${token}`,
270→          'User-Agent': 'TPMJS/1.0',
271→          ...(stdin ? { 'Content-Type': 'application/octet-stream' } : {}),
272→        },
273→        body: stdin || undefined,
274→        signal: controller.signal,
275→      });
276→
277→      clearTimeout(timeoutId);
278→    } catch (error) {
279→      if (error instanceof Error) {
280→        if (error.name === 'AbortError') {
281→          throw new Error(`Command execution in sprite "${name}" timed out after ${timeout}ms`);
282→        }
283→        throw new Error(`Failed to execute command in sprite "${name}": ${error.message}`);
284→      }
285→      throw new Error(`Failed to execute command in sprite "${name}": Unknown network error`);
286→    }
287→
288→    const duration = Date.now() - startTime;
289→
290→    if (!response.ok) {
291→      if (response.status === 404) {
292→        throw new Error(`Sprite "${name}" not found`);
293→      }
294→      if (response.status === 401) {
295→        throw new Error('Invalid SPRITES_TOKEN. Check your API token at https://sprites.dev');
296→      }
297→      const errorText = await response.text().catch(() => 'Unknown error');
298→      throw new Error(
299→        `Failed to execute command in sprite "${name}": HTTP ${response.status} - ${errorText}`
300→      );
301→    }
302→
303→    // Parse response - handle both binary and JSON error responses
304→    const arrayBuffer = await response.arrayBuffer();
305→    const buffer = new Uint8Array(arrayBuffer);
306→
307→    // Check if response is JSON error (starts with '{') instead of binary (starts with 0x00-0x03)
308→    // Sprites API returns HTTP 200 with JSON body for some errors like auth failures
309→    if (buffer.length > 0 && buffer[0] === 0x7b) {
310→      // 0x7B = '{'
311→      const decoder = new TextDecoder();
312→      const jsonText = decoder.decode(buffer);
313→      try {
314→        const errorResponse = JSON.parse(jsonText) as { error?: string };
315→        if (errorResponse.error) {
316→          throw new Error(`Failed to execute command in sprite "${name}": ${errorResponse.error}`);
317→        }
318→      } catch (parseError) {
319→        // If JSON parsing fails, throw generic error with raw text
320→        if (parseError instanceof SyntaxError) {
321→          throw new Error(`Failed to execute command in sprite "${name}": ${jsonText}`);
322→        }
323→        throw parseError;
324→      }
325→    }
326→
327→    const { stdout, stderr, exitCode } = parseBinaryResponse(buffer);
328→
329→    return {
330→      exitCode,
331→      stdout,
332→      stderr,
333→      duration,
334→    };
335→  },
336→});
337→
338→export default spritesExecTool;
