  1→/**
  2→ * @tpmjs/tools-resend — Resend Email API Tools for AI Agents
  3→ *
  4→ * Full access to the Resend email API: send emails, manage domains, contacts,
  5→ * broadcasts, audiences, and API keys.
  6→ *
  7→ * @requires RESEND_API_KEY environment variable
  8→ */
  9→
 10→import { jsonSchema, tool } from 'ai';
 11→
 12→const BASE_URL = 'https://api.resend.com';
 13→
 14→// ─── Client Infrastructure ──────────────────────────────────────────────────
 15→
 16→function getApiKey(): string {
 17→  const key = process.env.RESEND_API_KEY;
 18→  if (!key) {
 19→    throw new Error(
 20→      'RESEND_API_KEY environment variable is required. Get your API key from https://resend.com/api-keys'
 21→    );
 22→  }
 23→  return key;
 24→}
 25→
 26→async function apiRequest<T>(method: string, path: string, body?: unknown): Promise<T> {
 27→  const key = getApiKey();
 28→
 29→  const headers: Record<string, string> = {
 30→    Authorization: `Bearer ${key}`,
 31→    'Content-Type': 'application/json',
 32→  };
 33→
 34→  const options: RequestInit = { method, headers };
 35→  if (body !== undefined) {
 36→    options.body = JSON.stringify(body);
 37→  }
 38→
 39→  const response = await fetch(`${BASE_URL}${path}`, options);
 40→
 41→  if (!response.ok) {
 42→    await handleApiError(response);
 43→  }
 44→
 45→  const text = await response.text();
 46→  if (!text) {
 47→    return {} as T;
 48→  }
 49→
 50→  return JSON.parse(text) as T;
 51→}
 52→
 53→async function handleApiError(response: Response): Promise<never> {
 54→  let errorMessage: string;
 55→  try {
 56→    const errorData = (await response.json()) as { message?: string; error?: string };
 57→    errorMessage = errorData.message || errorData.error || `HTTP ${response.status}`;
 58→  } catch {
 59→    errorMessage = `HTTP ${response.status}: ${response.statusText}`;
 60→  }
 61→
 62→  switch (response.status) {
 63→    case 400:
 64→      throw new Error(`Bad request: ${errorMessage}`);
 65→    case 401:
 66→      throw new Error('Authentication failed: Invalid Resend API key. Check RESEND_API_KEY.');
 67→    case 403:
 68→      throw new Error(`Access forbidden: ${errorMessage}`);
 69→    case 404:
 70→      throw new Error(`Not found: ${errorMessage}`);
 71→    case 422:
 72→      throw new Error(`Validation error: ${errorMessage}`);
 73→    case 429:
 74→      throw new Error(`Rate limit exceeded: ${errorMessage}`);
 75→    default:
 76→      throw new Error(`Resend API error (${response.status}): ${errorMessage}`);
 77→  }
 78→}
 79→
 80→function buildQueryString(params: Record<string, unknown>): string {
 81→  const entries = Object.entries(params).filter(
 82→    ([, v]) => v !== undefined && v !== null && v !== ''
 83→  );
 84→  if (entries.length === 0) return '';
 85→  return (
 86→    '?' +
 87→    entries.map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`).join('&')
 88→  );
 89→}
 90→
 91→// ─── Emails ─────────────────────────────────────────────────────────────────
 92→
 93→export interface SendEmailInput {
 94→  from: string;
 95→  to: string | string[];
 96→  subject: string;
 97→  html?: string;
 98→  text?: string;
 99→  cc?: string | string[];
100→  bcc?: string | string[];

  1→/**
  2→ * @tpmjs/official-memory
  3→ *
  4→ * Persistent, semantically-searchable memory tools for AI agents.
  5→ * Requires a TPMJS API key with memory:read and memory:write scopes.
  6→ *
  7→ * Environment variables:
  8→ *   TPMJS_API_KEY  - Required. Your TPMJS Platform API key.
  9→ *   TPMJS_BASE_URL - Optional. Defaults to https://tpmjs.com
 10→ */
 11→
 12→import { jsonSchema, tool } from 'ai';
 13→
 14→// ---------------------------------------------------------------------------
 15→// Config helpers
 16→// ---------------------------------------------------------------------------
 17→
 18→function getConfig(): { apiKey: string; baseUrl: string } {
 19→  const apiKey = process.env.TPMJS_API_KEY;
 20→  if (!apiKey) {
 21→    throw new Error(
 22→      'TPMJS_API_KEY environment variable is required. ' +
 23→        'Get one at https://tpmjs.com/dashboard/settings/tpmjs-api-keys'
 24→    );
 25→  }
 26→  const baseUrl = (process.env.TPMJS_BASE_URL || 'https://tpmjs.com').replace(/\/$/, '');
 27→  return { apiKey, baseUrl };
 28→}
