47→      },
48→    },
49→    required: ['data'],
50→    additionalProperties: false,
51→  }),
52→  execute: async ({ data, encoding = 'utf8' }): Promise<Base64EncodeResult> => {
53→    // Validate input
54→    if (typeof data !== 'string') {
55→      throw new Error('Data must be a string');
56→    }
57→
58→    // Validate encoding
