 41→  }
 42→
 43→  const response = await fetch(`${BASE_URL}/${method}`, options);
 44→
 45→  if (!response.ok) {
 46→    throw new Error(`Slack HTTP error ${response.status}: ${response.statusText}`);
 47→  }
 48→
