 59→  const token = getApiKey();
 60→
 61→  const qs = buildQueryString(params);
 62→  const url = `${BASE_URL}/${method}${qs}`;
 63→
 64→  const headers: Record<string, string> = {
 65→    Authorization: `Bearer ${token}`,
 66→  };
 67→
 68→  const response = await fetch(url, { method: 'GET', headers });
 69→
 70→  if (!response.ok) {
 71→    throw new Error(`Slack HTTP error ${response.status}: ${response.statusText}`);
 72→  }
 73→
 74→  const data = (await response.json()) as { ok: boolean; error?: string } & T;
